insert into public.questions (id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, category, difficulty) values
  ('a4eba4e6-eacc-58f8-9474-7a37cc15aefb', 'Caso clínico: Lactante de 10 meses, letárgico, madre refiere que no ha podido darle el pecho en las últimas horas y que vomita todo lo que le ofrece. ¿Cuál es la conducta INMEDIATA correcta según el AIEPI?', 'Clasificar como Enfermedad muy grave, completar la evaluación de inmediato y referir urgente al hospital', 'Iniciar amoxicilina oral y citar en 3 días', 'Dar zinc y SRO en casa', 'Esperar la próxima consulta de control de niño sano', 'A', 'La letargia, la incapacidad de beber/tomar el seno y el vómito de todo lo que ingiere son signos de peligro en general. Cualquiera de ellos clasifica como Enfermedad muy grave: se debe completar la evaluación urgente y referir de inmediato aplicando REFIERA (p.6, 60).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('417f69e5-ceae-53be-afa9-05aec3a53a11', 'Caso clínico: Niño de 3 años, sin signos de peligro, con respiración de 42/min y sin tiraje subcostal. ¿Cuál es el manejo correcto?', 'Ceftriaxona IM y referencia urgente', 'Amoxicilina a dosis altas por 3 días, manejo ambulatorio', 'Salbutamol inhalado y seguimiento en 5 días', 'Solo manejo sintomático con remedio casero', 'B', 'Respiración rápida SIN tiraje subcostal ni signos de peligro clasifica como Neumonía. Con solo respiración rápida corresponde amoxicilina a dosis altas por 3 días, de forma ambulatoria (nota a, p.7).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('3adfbd93-5f2e-5223-83b3-2e97c84cfa2e', 'Caso clínico: Niña de 20 meses con diarrea, letárgica, ojos hundidos, bebe mal, pliegue cutáneo muy lento. Sin otra clasificación grave. El establecimiento puede canalizar vía IV de inmediato. ¿Cuál es el manejo correcto?', 'Plan B en el establecimiento', 'Plan A en casa', 'Plan C en la unidad de salud: 100mL/kg de Lactato Ringer en 3 horas (50-25-25)', 'Referir de inmediato sin iniciar hidratación', 'C', '4 signos de deshidratación grave sin otra clasificación grave y con capacidad de IV → Plan C en el sitio: 50mL/kg 1ª hora, 25mL/kg 2ª hora, 25mL/kg 3ª hora, reevaluando después (p.8, 26).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('d1e3ab0b-d733-5bfa-ba94-3ac9973fcfbd', 'Caso clínico: Niño de 2 años con estridor en reposo, retracción torácica leve, entrada de aire audible, nivel de conciencia normal. Se puede supervisar 4-5 horas en el establecimiento. ¿Cuál es la conducta correcta?', 'Solo aumentar la ingesta de líquidos, sin corticoide', 'Antibiótico oral y salbutamol inhalado', 'Referir urgente sin tratar en el sitio', '1 dosis de corticoide (preferible VO) y observar; nebulizar adrenalina si no mejora en 2 horas', 'D', 'Crup moderado supervisable: corticoide (preferiblemente oral) y observación; si no hay mejoría en 2h o empeora, nebulizar con adrenalina. Antibióticos y salbutamol NO están indicados en el crup (p.21).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('9f134e9a-d7f6-5a2b-b841-5e6d3f260141', 'Caso clínico: Niño de 4 años en zona de riesgo de dengue, fiebre de 3 días, hoy con vómito persistente y dolor abdominal intenso continuo. ¿Cuál es el manejo correcto?', 'Hidratación IV según plan de hidratación de dengue, notificar y referir urgente', 'Paracetamol e ibuprofeno alternados en casa', 'Antibiótico IM antes de referir', 'Manejo ambulatorio con control en 5 días', 'A', 'Vómito persistente y dolor abdominal intenso continuo son signos de alarma (DCSA): hidratación IV (dosis de carga 10mL/kg/h), notificación a epidemiología y referencia urgente. Nunca AINES ni vía IM/rectal (p.9).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('1b3ff7fb-8b3c-596e-9703-4da7334a7063', 'Caso clínico: Niña de 14 meses con edema en ambos pies y riesgo social identificado (madre adolescente sin apoyo). ¿Cuál es la conducta correcta?', 'ATLU ambulatorio y control en 15 días', 'Notificación, vitamina A, primera dosis de antibiótico apropiado y referencia urgente', 'Solo consejería nutricional', 'Zinc por 14 días y alta', 'B', 'Edema bilateral = desnutrición aguda; con riesgo social (criterio de complicación) → Desnutrición aguda severa CON complicación: notificar, vitamina A, 1ª dosis de antibiótico, referir urgente (p.12, 60).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('b1753001-c101-5125-b7cc-122f90adac3d', 'Caso clínico: Niño de 2 años con palidez palmar intensa; hemoglobina de 6.8 g/dL. ¿Cuál es la conducta correcta?', 'Micronutrientes en polvo y control en 14 días', 'Hierro en gotas por 3 meses de forma ambulatoria', 'Referir urgente al hospital aplicando REFIERA', 'Transfusión ambulatoria en el establecimiento', 'C', 'Palidez palmar intensa o Hb<7g/dL clasifica como Anemia grave: referencia urgente al hospital según REFIERA (p.14, 60).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('d1d6b769-5261-5f10-82df-1d1a083cd1e2', 'Caso clínico: Niño de 4 años con antecedente de sibilancias, hoy no puede hablar en frases, cianosis central, saturación 86%. ¿Cuál es el manejo correcto?', 'Observación sin tratamiento hasta reevaluar en 1 hora', 'Salbutamol en casa y control en 2 días', 'Solo corticoide oral sin salbutamol', 'Oxígeno, salbutamol inhalado, primera dosis de corticoide y referencia urgente', 'D', 'Signos de gravedad (no habla en frases, cianosis, SatO2<90%) → Crisis de sibilancia recurrente grave: oxígeno + salbutamol + 1ª dosis de corticoide + referencia urgente (p.19).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('463dc441-d1ba-58ba-931a-bf8c70b43464', 'Caso clínico: Niño de 3 años, sano, no desnutrido, con dolor de oído y secreción de 2 días, sin otitis bilateral. Según la guía, ¿qué opción de manejo es válida además del antibiótico inmediato?', 'Tratamiento diferido: antibiótico solo si no mejora tras 3 días', 'Cirugía de urgencia', 'Referencia hospitalaria obligatoria', 'Ciprofloxacina oral inmediata', 'A', 'En >2 años, sin mal estado general, sin desnutrición, sin otitis bilateral con secreción y sin prematuridad, se puede proponer tratamiento diferido (nota, p.11).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('b6264d2d-f385-562d-975d-d6aca8fbf376', 'Caso clínico: Niño de 3 años en zona de alto riesgo de malaria, gota gruesa positiva, y anemia moderada detectada en la misma consulta. ¿Cuál es la secuencia correcta de manejo?', 'Iniciar hierro y antimalárico el mismo día sin orden específico', 'Tratar primero la malaria; iniciar hierro después de haber iniciado/completado el antimalárico', 'Iniciar solo hierro y diferir la malaria', 'No tratar la anemia hasta el control de los 3 meses', 'B', 'La guía indica explícitamente: en zona de alto riesgo de malaria, si la gota gruesa es positiva, tratar primero la malaria antes de tratar la anemia con hierro (p.28).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('1904f6ad-32ec-5471-8f32-89b2136d3315', 'Caso clínico: Niña de 2 años (12 kg) con convulsiones activas al ingreso. ¿Cuál es el manejo farmacológico inmediato correcto?', 'Diazepam intravenoso diluido en dextrosa', 'Fenobarbital oral inmediato', 'Diazepam intrarrectal 1-2 mL sin diluir, repitiendo una segunda dosis si continúa tras 10 minutos', 'Ningún medicamento hasta llegar al hospital', 'C', 'Ante convulsiones (Enfermedad muy grave), se administra diazepam intrarrectal sin diluir según peso (1-2mL para 12-23kg); si continúa tras 10 min, segunda dosis (p.24).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('633b19d4-5409-5501-ba50-f3790fb263ee', 'Caso clínico: Niño de 18 meses con longitud/talla por debajo de -2DE, sin diarrea actual. ¿Cuál es una de las conductas correctas?', 'Administrar antibiótico oral', 'Referir urgente al hospital', 'Solo control en 6 meses sin intervención', 'Dar zinc durante 12 semanas, evaluar y corregir la alimentación', 'D', 'Talla baja en 6-23 meses: zinc por 12 semanas, evaluar/corregir alimentación, micronutrientes, visita domiciliaria y monitoreo en 30 días (p.13).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('984283a6-3834-56f5-8e54-aa35ffeec919', 'Caso clínico: Niño de 4 años con sangre en heces, fiebre y cólicos abdominales. ¿Cuál es la conducta correcta antes de referir?', 'Dar una dosis de ciprofloxacina antes de referir, tras clasificar/tratar la deshidratación', 'No dar antibiótico, solo referir', 'Dar amoxicilina IM', 'Esperar resultado de coprocultivo antes de cualquier tratamiento', 'A', 'Disentería grave: clasificar y tratar la deshidratación, dar una dosis de antibiótico apropiado (ciprofloxacina) antes de referir, y referir urgente (p.8, 22).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('f0661fc8-79a4-5444-a70c-c86479e2b7a1', 'Caso clínico: Niño de 2 años con erupción cefalocaudal no vesicular, tos y ojos enrojecidos, sin megadosis de vitamina A en el último mes. ¿Cuál es la conducta correcta?', 'Aislamiento sin tratamiento ni notificación', 'Dar vitamina A, paracetamol si fiebre alta, y notificar el caso a epidemiología', 'Antibiótico oral de amplio espectro', 'Vacunar contra SRP de inmediato como tratamiento', 'B', 'Sospecha de sarampión: vitamina A (salvo megadosis reciente), paracetamol si fiebre alta, y notificación obligatoria a epidemiología (p.10).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('ed17e34d-4651-5603-94ec-70b68b27be5e', 'Caso clínico: Niña de 3 años con fractura de extremidad y marcas de mordedura humana. ¿Cuál es la conducta correcta?', 'No es necesario notificar si los padres lo niegan', 'Solo dar analgesia y citar en 14 días', 'Tratar las lesiones, referir urgente y notificar a la autoridad competente de protección de la niñez', 'Manejo exclusivamente ambulatorio con seguimiento en consulta externa', 'C', 'Fractura y marcas de mordedura son criterios de ''Compatible con maltrato físico y/o abuso sexual'': tratar lesiones, referir urgente, notificar y coordinar con protección de menores (p.15).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('5992b159-f3b4-5205-9222-8d6979a5de20', 'Caso clínico: Recién nacido de 4 días con temperatura axilar de 35.2°C, hipoactivo. ¿Cuál es la conducta correcta?', 'Alta con indicación de lactancia exclusiva únicamente', 'Solo abrigarlo en casa y control en 7 días', 'Baño con agua tibia para subir la temperatura', '1ª dosis IM de antibióticos recomendados y referencia urgente aplicando REFIERA', 'D', 'Hipotermia (<35.5°C) es criterio único de Enfermedad muy grave en el neonato: antibiótico IM + REFERIR URGENTE, aplicando el componente F (frío=mortal) de REFIERA (p.56, 60-61).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('8ee3ab2b-6701-563c-a52b-30360fc28b47', 'Caso clínico: Recién nacido de 20 horas de vida con ictericia visible en cara y tronco. ¿Cuál es la conducta correcta?', 'Referir urgentemente al hospital', 'Continuar lactancia y control en 1 día sin mayor evaluación', 'Fototerapia domiciliaria improvisada con luz solar', 'Esperar hasta las 48 horas para reevaluar', 'A', 'Cualquier ictericia en las primeras 24 horas de vida clasifica como Ictericia grave, independiente de su extensión: referencia urgente (p.57).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('465bfe60-fbaa-5ace-8155-939b5e17c8e5', 'Caso clínico: Gestante de 30 semanas con ruptura prematura de membranas, sin trabajo de parto activo. ¿Cuál es el manejo correcto antes de referir?', 'Solo observación, sin medicación', 'Maduración pulmonar (dexametasona o betametasona) + ampicilina IV/IM más eritromicina VO', 'Cesárea inmediata en el sitio', 'Tocolisis con nifedipina en dosis altas indefinidamente', 'B', 'RPM entre 24 y 34.6 semanas: iniciar maduración pulmonar fetal (dexametasona/betametasona) y dar ampicilina + eritromicina como profilaxis antibiótica antes de referir (p.44).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('028ed17d-f614-53e7-8fd9-6157adeda362', 'Caso clínico: Recién nacido de 30 horas con saturación de oxígeno de 90% en la mano derecha. ¿Cuál es la conducta correcta según el algoritmo de tamizaje?', 'Dar de alta porque no hay cianosis visible', 'Repetir la prueba en 1 hora únicamente', 'Es positivo inmediato: referir al hospital al cardiólogo pediatra o buscar causa de hipoxemia', 'Repetir el tamizaje a los 7 días', 'C', 'SatO2<92% en mano derecha es ''positivo inmediato'': referir a cardiología pediátrica o investigar causa de hipoxemia, sin esperar repetición horaria (p.92).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('137fcc6b-a490-5f6e-8877-21a716a5a454', 'Caso clínico: Niño de 8 meses, 6 kg, con desnutrición aguda severa sin criterios de complicación. ¿Cuál es la conducta correcta respecto a la prueba del apetito?', 'La prueba solo aplica a niños con desnutrición moderada', 'No debe realizarse por ser menor de 6 meses', 'Remitir directamente a manejo intrahospitalario sin evaluar el apetito', 'Realizar la prueba: si consume más de 1/4 del sobre de ATLU, puede manejarse en el hogar', 'D', 'Para 6-59 meses con peso 4-6.9kg, consumo >1/4 del sobre = prueba positiva → manejo ambulatorio con ATLU. El niño tiene 8 meses (no <6m) y 6kg, por lo que sí corresponde realizar la prueba (p.91).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Casos UEES'),
  ('4b3b514b-6aad-5817-a0f9-da9255e356a7', 'Caso clínico: Un niño de 14 meses es traído a consulta por su madre. Al preguntar, ella refiere que el niño ha vomitado todo lo que le ha dado de comer en las últimas 4 horas y que ''no reacciona como siempre''. Según el cuadro de evaluación de signos de peligro en general, ¿cuál es la clasificación y conducta inmediata?', 'Enfermedad muy grave; referir urgente al hospital aplicando REFIERA', 'Neumonía; dar amoxicilina ambulatoria', 'Deshidratación; iniciar Plan B', 'Diarrea persistente; dar zinc por 14 días', 'A', 'Vomitar todo lo que ingiere es uno de los signos de peligro en general listados en el cuadro EVALUAR de la página 6. La presencia de cualquiera de estos signos clasifica al niño como ENFERMEDAD MUY GRAVE, cuya conducta es completar de inmediato la evaluación, administrar diazepam intrarrectal si convulsiona y referir URGENTE al hospital aplicando las normas de estabilización y transporte REFIERA. Referencia: Evaluar y clasificar a la niña o niño de 2 meses a menor de 5 años, 1. Verificar si hay signos de peligro en general, cuadro Evaluar-Clasificar-Decidir y tratar, p. 6.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('e37a4316-9a3a-53be-996a-d4741de224a7', 'Según la guía, ¿cuáles de los siguientes son considerados signos de peligro en general que obligan a clasificar a una niña o niño de 2 meses a menor de 5 años como Enfermedad muy grave?', 'Tos de más de 21 días y fiebre de 3 días', 'No puede beber o tomar el seno, vomita todo lo que ingiere, ha tenido o tiene convulsiones, o está letárgico/inconsciente', 'Respiración rápida y tiraje subcostal', 'Ojos hundidos y signo del pliegue cutáneo positivo', 'B', 'El cuadro de la página 6 establece que ante cualquiera de los siguientes signos —no puede beber o tomar el seno, vomita todo lo que ingiere, ha tenido o tiene convulsiones, está letárgico o inconsciente— se debe clasificar como Enfermedad muy grave y dar atención urgente. Referencia: Evaluar y clasificar a la niña o niño de 2 meses a menor de 5 años, 1. Verificar si hay signos de peligro en general, p. 6.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('37590c3b-9169-5e18-b8d3-ef4e92692332', 'Caso clínico: Una niña de 3 años llega inconsciente al establecimiento de salud y en ese momento presenta convulsiones activas. Según la guía, ¿cuál es la conducta inmediata indicada además de referir urgente al hospital?', 'Iniciar Plan A de hidratación', 'Administrar amoxicilina oral', 'Administrar diazepam intrarrectal', 'Aplicar vitamina A en megadosis', 'C', 'El cuadro Decidir y tratar de la clasificación Enfermedad muy grave (p.6) indica que si la niña o niño está convulsionando se debe administrar diazepam intrarrectal, cuyo procedimiento de administración se describe en la página 24, además de completar la evaluación y referir urgente al hospital. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Enfermedad muy grave, Decidir y tratar, p. 6; Administrar diazepam intrarrectal para controlar convulsiones, p. 24.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('5e8c664c-436e-5cf8-bd26-7b1102f38fac', 'Caso clínico: Un lactante de 4 meses presenta su primer episodio de sibilancias, con antecedente de cuadro gripal 2 días antes. Al examen: tiraje subcostal presente, frecuencia respiratoria de 55 por minuto, no cianosis, satura 95%. ¿Cómo debe clasificarse a este lactante según el cuadro de obstrucción de la vía aérea?', 'Crup', 'Bronquiolitis', 'Sibilancia recurrente', 'Bronquiolitis grave', 'D', 'Se trata de un primer episodio de sibilancias en un menor de 2 años con cuadro gripal 1 a 3 días antes; presenta tiraje subcostal y respiración rápida (≥50/min para su edad), criterios listados en el cuadro de Bronquiolitis grave de la página 6. Basta con uno de estos criterios para clasificar como Bronquiolitis grave, lo que exige oxígeno si es posible y referencia urgente. Referencia: Evaluar y clasificar a la niña o niño de 2 meses a menor de 5 años, 2.1 Clasificar primero la obstrucción de la vía aérea, cuadro Bronquiolitis grave, p. 6.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('3661ddcc-7911-55fc-a3c9-24369c48f216', 'De acuerdo con la guía, ¿cuál es la conducta correcta ante una niña o niño clasificado como Bronquiolitis (no grave)?', 'Aumentar ingesta de líquidos y leche materna, realizar limpieza nasal con suero fisiológico, sin antibiótico ni salbutamol ni corticoides, con seguimiento en 2 días', 'Administrar antibiótico oral y salbutamol inhalado', 'Referir urgente al hospital aplicando REFIERA', 'Nebulizar con adrenalina y dar corticoide sistémico', 'A', 'La guía indica explícitamente que en la clasificación Bronquiolitis se debe realizar limpieza nasal con suero fisiológico cada 3-4 horas, aumentar la ingesta de líquidos y leche materna, enseñar a la madre los signos de alarma, y que NO se debe administrar antibiótico NI salbutamol NI corticoides porque no están indicados; se cita a consulta de seguimiento en dos días. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Bronquiolitis, Decidir y tratar, p. 6.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('fb94feaa-b0d4-518c-9e42-364fac3d0517', 'Caso clínico: Un niño de 2 años sin signos de peligro en general ni saturación baja presenta tiraje subcostal y respiración de 52 por minuto. Según el cuadro de clasificación de tos o dificultad respiratoria (sin obstrucción de vía aérea), ¿cuál es la clasificación y el esquema de amoxicilina indicado?', 'Neumonía grave; ceftriaxona IM', 'Neumonía; amoxicilina a dosis altas por 5 días', 'Tos o resfriado; remedio casero', 'Neumonía; amoxicilina a dosis altas por 3 días', 'B', 'Al no tener signos de enfermedad muy grave ni saturación <90%, pero presentar tiraje subcostal, se clasifica como Neumonía. Según la nota (a) de la página 7, basada en recomendaciones de la OMS, cuando la niña o niño clasificado como Neumonía tiene tiraje subcostal (sin signos de peligro en general) se trata de manera ambulatoria con amoxicilina a dosis altas (80-90 mg/kg/día) por vía oral durante 5 días. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, 2.2 Clasificar la tos o dificultad respiratoria, cuadro Neumonía, y nota (a), p. 7.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('76de21e4-d323-5a1e-b621-6a149ceecd19', 'Una niña de 18 meses presenta tos, dificultad para respirar y saturación de oxígeno de 88%. ¿Cuál es la clasificación correcta y la conducta inicial?', 'Tos o resfriado; seguimiento en 5 días', 'Neumonía; amoxicilina ambulatoria', 'Enfermedad muy grave o neumonía grave; primera dosis de antibiótico apropiado, oxígeno si es posible y referencia urgente', 'Bronquiolitis grave; oxígeno y aumento de líquidos', 'C', 'Según el cuadro de la página 7, una saturación de oxígeno menor de 90% clasifica de inmediato como Enfermedad muy grave o neumonía grave, cuya conducta es dar la primera dosis de un antibiótico apropiado, administrar oxígeno si es posible y referir urgente al hospital siguiendo las normas de estabilización y transporte. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, 2.2, cuadro Enfermedad muy grave o neumonía grave, p. 7.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('f9b954bd-aa73-556f-ad67-7422fa327f71', 'Según el cuadro de tratamiento de sibilancia, ¿cuál es el esquema correcto de salbutamol inhalado para el primer episodio antes de reclasificar?', '4 atomizaciones cada 2 horas por 24 horas', '1 atomización única sin repetición', 'Nebulización continua con adrenalina', '2 atomizaciones (puff) con aerocámara, repetidas cada 15-20 minutos hasta 3 veces en 1 hora', 'D', 'La guía indica que ante un primer episodio de sibilancia se debe dar 2 atomizaciones (puff) de salbutamol en spray con inhalocámara, repitiendo cada 15-20 minutos hasta por 3 veces durante 1 hora si es necesario, para luego valorar y reclasificar según la respuesta. Referencia: Tratar a la niña o niño de 2 meses a menor de 5 años de edad con sibilancia; Administrar broncodilatador de acción rápida (salbutamol) en aerosol, p. 19-20.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('236f33e7-979d-56c5-86b2-93fac6f4ceef', 'Caso clínico: Un niño de 3 años con antecedente de sibilancias recurrentes presenta hoy incapacidad para hablar, cianosis central y saturación de oxígeno de 87%. ¿Cuál es la clasificación y el manejo inicial correcto?', 'Crisis de sibilancia recurrente grave; oxígeno, salbutamol inhalado con aerocámara, primera dosis de corticoide y referencia urgente', 'Crisis de sibilancia recurrente leve a moderada; salbutamol en casa', 'Bronquiolitis; limpieza nasal y seguimiento en 2 días', 'Crup grave; nebulización con adrenalina', 'A', 'La incapacidad de hablar, la cianosis central y la saturación de oxígeno <90% son signos de gravedad listados en el cuadro de sibilancia recurrente (p.19), que clasifican como Crisis de sibilancia recurrente grave. La conducta indicada es administrar oxígeno, salbutamol inhalado con aerocámara, la primera dosis de corticoide y referir urgente al hospital según las normas de estabilización y transporte. Referencia: Tratar a la niña o niño de 2 meses a menor de 5 años con sibilancia, cuadro Crisis de sibilancia recurrente grave, p. 19.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('6b1f5020-90d5-5ae7-a5a6-c33b0924bd7b', 'Caso clínico: Una niña de 2 años presenta estridor agudo. Al examen tiene nivel de conciencia normal, estridor inspiratorio leve, retracción torácica leve y entrada de aire disminuida pero audible. ¿Cuál es la clasificación correspondiente según el cuadro de CRUP?', 'Crup grave', 'Crup moderado', 'Crup leve', 'Bronquiolitis grave', 'B', 'El nivel de conciencia normal junto con estridor inspiratorio leve a moderado y/o retracción torácica leve a moderada y entrada de aire disminuida pero audible corresponden exactamente a los criterios de Crup moderado descritos en el cuadro de la página 21. Referencia: Evaluar, clasificar y tratar a la niña o niño de 2 meses a menor de 5 años con CRUP, cuadro Crup moderado, p. 21.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('1773f156-986d-5a96-be21-cd737b032752', '¿Cuál de las siguientes afirmaciones sobre el manejo del crup es correcta según la guía?', 'La adrenalina puede administrarse por cualquier vía según disponibilidad', 'El salbutamol inhalado y los antibióticos están indicados de forma sistemática', 'Los antibióticos y el salbutamol NO están indicados en el manejo del crup', 'El diagnóstico se confirma con radiografía de tórax de rutina', 'C', 'La guía establece explícitamente en un recuadro destacado que los antibióticos y el salbutamol NO están indicados en el manejo del crup, ya que se trata de una obstrucción laríngea de origen viral que se maneja con corticoide y, en casos graves o moderados con mala evolución, adrenalina nebulizada. Referencia: Evaluar, clasificar y tratar a la niña o niño de 2 meses a menor de 5 años con CRUP, p. 21.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('5d26af29-9987-5ae1-a290-69348a37ac3d', 'Caso clínico: Un niño tratado con amoxicilina por Neumonía regresa a control a los 3 días. La madre refiere que la respiración es más lenta, que bajó la fiebre y que el niño está comiendo mejor. ¿Cuál es la conducta correcta en esta consulta de seguimiento?', 'Suspender inmediatamente el antibiótico por mejoría clínica', 'Referir urgente al hospital por falta de respuesta', 'Cambiar a antibiótico intramuscular', 'Completar el tratamiento de 3 o 5 días con amoxicilina y citar a nueva consulta integral', 'D', 'La guía indica que en el seguimiento de neumonía a los 3 días, si la respiración se ha normalizado, bajó la fiebre o el niño come mejor, se debe completar el tratamiento de 3 o 5 días con amoxicilina (según la clasificación inicial) y citar a una nueva consulta de atención integral. Referencia: Proporcionar atención de seguimiento y reevaluación, Neumonía, después de 3 días, p. 30.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('cb6dc48e-7ed7-5d8d-af20-cb791ef95b20', 'Al enseñar a una madre a administrar salbutamol en aerosol con inhalocámara a su hijo, ¿cuál de los siguientes pasos es correcto según el procedimiento descrito en la guía?', 'Agitar el inhalador, adaptarlo a la inhalocámara, colocarlo sobre boca y nariz sin fuga de aire, administrar un puff contando de 1 a 5 (o 5 respiraciones), y repetir con un segundo puff', 'Administrar los 2 puff de forma simultánea sin contar respiraciones', 'Aplicar el spray directamente en la boca sin usar inhalocámara para mayor efecto', 'Esperar 5 minutos entre cada ciclo de inhalación', 'A', 'El procedimiento descrito en la guía establece: agitar el inhalador, quitar la tapa, adaptarlo a la inhalocámara, colocar el extremo abierto sobre la boca y nariz del niño evitando fuga de aire, contar de 1 a 5 (o dejar que respire 5 veces), administrar un puff presionando el inhalador una vez y contar nuevamente, luego administrar un segundo puff de la misma manera. Referencia: Administrar broncodilatador de acción rápida (salbutamol) en aerosol en caso de sibilancias, p. 20.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('be3305f4-628b-5acc-876c-8443b104713b', 'Caso clínico: Un niño con crup leve, que pesa 8 kg, requiere tratamiento con corticoide. Según la tabla de dosificación de la guía, ¿cuál es la dosis aproximada de dexametasona indicada?', '1 mg', '2 mg', '3 mg', '5 mg', 'B', 'Según la tabla de dosificación de dexametasona (0.15-0.6 mg/kg/dosis) de la página 21, para un peso de 7 a 9 kg corresponde una dosis de 2 mg. Referencia: Evaluar, clasificar y tratar a la niña o niño con CRUP, tabla Dexametasona, p. 21.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('671a1b72-d693-5d44-8a74-8d16de8c4faa', 'Según la guía, ¿por qué vía debe administrarse la adrenalina en el manejo del crup?', 'Subcutánea', 'Intramuscular únicamente', 'Únicamente por vía nebulizada', 'Intravenosa directa', 'C', 'La guía especifica claramente en el recuadro de dosificación de adrenalina que ''solo la vía nebulizada es apropiada'' para el manejo del crup, con una dosis de 0.5 mg/kg (máximo 5 mL/5 mg) diluida en solución salina al 0.9% hasta completar 10 mL en el recipiente del nebulizador. Referencia: Evaluar, clasificar y tratar a la niña o niño con CRUP, recuadro Adrenalina al 1/1000, p. 21.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('9be887be-aeca-5194-aa35-d919df5df7af', 'Caso clínico: Una niña de 20 meses con diarrea presenta los ojos hundidos, está letárgica y el signo del pliegue cutáneo vuelve al estado anterior muy lentamente (más de 2 segundos). ¿Cuál es la clasificación de la deshidratación y el tratamiento inicial recomendado si no presenta otra clasificación grave?', 'Diarrea persistente; vitamina A', 'No tiene deshidratación; Plan A', 'Deshidratación; Plan B', 'Deshidratación grave; Plan C en la unidad de salud', 'D', 'La presencia de dos de los signos siguientes —letárgico/inconsciente, ojos hundidos, bebe mal o no puede beber, signo del pliegue cutáneo que vuelve muy lentamente— clasifica como Deshidratación grave. En este caso hay letargia, ojos hundidos y pliegue cutáneo muy lento (tres signos). Si la niña no tiene otra clasificación grave, se administra el Plan C en la unidad de salud. Referencia: Evaluar y clasificar a la niña o niño de 2 meses a menor de 5 años, 3. ¿Tiene la niña o niño diarrea?, cuadro Deshidratación grave, p. 8.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('f29095f3-3610-57ac-b188-d7aad2e7a373', 'Caso clínico: Un niño de 3 años presenta diarrea con sangre en las heces, fiebre y dolor abdominal tipo cólico. ¿Cuál es la clasificación correcta y la conducta a seguir antes de referir?', 'Disentería grave; clasificar y tratar la deshidratación, aplicar una dosis de antibiótico apropiado antes de referir, y referir aplicando REFIERA', 'Disentería; zinc por 14 días y seguimiento en 3 días', 'Diarrea persistente grave; vitamina A', 'Deshidratación; Plan B', 'A', 'La presencia de sangre en las heces junto con fiebre o cólicos abdominales o dificultad/dolor al orinar o defecar clasifica como Disentería grave. La conducta indicada es clasificar y tratar la deshidratación según el cuadro correspondiente antes de referir, aplicar una dosis de un antibiótico apropiado antes de referir a la niña o niño, y referir al hospital aplicando las normas REFIERA. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Disentería grave, p. 8; Dar antibiótico apropiado para casos de disentería, p. 22.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('267efffa-174e-5aa0-9a61-25181f09e81c', 'Caso clínico: Un niño de 14 meses que pesa 11 kg es clasificado con Deshidratación y debe recibir Plan B en el establecimiento de salud. Según la tabla de cantidades de SRO del Plan B, ¿qué cantidad aproximada de SRO debe administrarse durante las primeras 4 horas?', '200-450 mL', '800-960 mL', '450-800 mL', '960-1600 mL', 'B', 'Según la tabla del Plan B (p.25), para un niño de 12 meses a menor de 2 años (o peso de 10 a <12 kg), la cantidad de SRO a administrar durante las primeras 4 horas es de 800 a 960 mL. Referencia: Plan B: Tratar la deshidratación con SRO, tabla de cantidad de SRO en las primeras 4 horas, p. 25.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('146b2f3f-2698-5cd6-912b-019b79b1b788', 'Caso clínico: Un lactante con deshidratación grave llega a un establecimiento de salud donde sí se puede administrar de inmediato líquidos por vía intravenosa. Según el Plan C, ¿cuál es el esquema correcto de administración de Lactato de Ringer (100 mL/kg) en las primeras 3 horas?', 'Administrar todo el volumen en la primera hora', 'Primera hora 25 mL/kg, segunda hora 50 mL/kg, tercera hora 25 mL/kg', 'Primera hora 50 mL/kg, segunda hora 25 mL/kg, tercera hora 25 mL/kg', 'Primera hora 33 mL/kg, segunda hora 33 mL/kg, tercera hora 34 mL/kg', 'C', 'El Plan C establece que, cuando es posible administrar líquidos IV de inmediato, se debe dar 100 mL/kg de Lactato de Ringer (o solución salina si no hubiera) de la siguiente manera: primera hora 50 mL/kg, segunda hora 25 mL/kg y tercera hora 25 mL/kg, vigilando constantemente y evaluando cada hora. Referencia: Plan C: Tratar rápidamente la deshidratación grave, tabla de administración de Lactato de Ringer, p. 26.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('b5a4d70b-8dd2-517d-af19-1c0951c6e383', 'En el seguimiento de una niña con diarrea persistente sin deshidratación, después de 5 días, ¿en qué situación se debe referir a un establecimiento de salud donde se puedan realizar exámenes de orina y heces?', 'Cuando la fiebre cedió tras el tratamiento', 'Cuando la diarrea disminuyó y el niño come mejor', 'Cuando el niño terminó el esquema de zinc sin complicaciones', 'Cuando la diarrea continúa, con tres o más evacuaciones acuosas al día', 'D', 'La guía indica que en el seguimiento de diarrea persistente a los 5 días, si la diarrea continúa (definida como tres o más evacuaciones acuosas por día), se debe referir a un establecimiento de salud donde se puedan realizar exámenes de orina (para descartar infección de vías urinarias) y de heces, tratando la giardiasis con metronidazol solo si se observan quistes o trofozoítos de Giardia lamblia. Referencia: Proporcionar atención de seguimiento y reevaluación, Diarrea persistente, después de 5 días, p. 30.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('be06265f-2f4a-5e78-ab76-c49b53eb96fb', 'Caso clínico: Una niña de 8 meses tiene diarrea desde hace 16 días, sin sangre en heces y sin signos de deshidratación. ¿Cuál es la clasificación correcta y una de las conductas indicadas?', 'Diarrea persistente; dar vitamina A (salvo megadosis reciente) y zinc por 14 días', 'Diarrea persistente grave; referir al hospital', 'Disentería; antibiótico apropiado', 'No tiene deshidratación; Plan A únicamente', 'A', 'Una diarrea de 14 días o más sin signos de deshidratación se clasifica como Diarrea persistente. La conducta incluye dar vitamina A (p.28) excepto si ya recibió una megadosis en el último mes, dar zinc por 14 días (p.23), explicar cómo alimentar a la niña con diarrea persistente y recomendar continuar dando el seno. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Diarrea persistente, p. 8.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('b9e5c411-6fac-5007-93ca-eb23b6a4c89f', 'Caso clínico: Un lactante de 7 meses con diarrea aguda requiere tratamiento con zinc. Según la tabla de dosificación de zinc para tratamiento de la diarrea, ¿cuál es la dosis correcta y la duración del tratamiento?', '10 mg una vez al día por 14 días', '20 mg una vez al día por 14 días', '20 mg dos veces al día por 7 días', '10 mg una vez al día por 7 días', 'B', 'Según la tabla A de dosificación de zinc para el tratamiento de la diarrea (aguda, persistente y disentería), para niñas y niños de 6 meses o más la dosis es de 20 mg una vez al día durante 14 días. Referencia: Enseñar a los padres o cuidadores a administrar los medicamentos en casa, ZINC, cuadro A. Zinc para tratamiento de la diarrea, p. 23.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('2d0e56d9-2f62-529e-8199-ccde4129bf66', 'Caso clínico: Un lactante de 5 meses presenta Deshidratación grave y, además, está clasificado como Enfermedad muy grave por letargia. ¿Cuál es la conducta correcta según el cuadro de diarrea?', 'Administrar Plan A en casa', 'Administrar Plan C en la unidad de salud sin referir', 'Referir urgente al hospital, dándole a la madre sorbos de SRO frecuentes durante el trayecto si el niño puede beber', 'Esperar 24 horas para reevaluar antes de decidir conducta', 'C', 'El cuadro de deshidratación grave especifica que si la niña o niño TIENE otra clasificación grave (como Enfermedad muy grave), se debe referir URGENTE al hospital según las normas de estabilización y transporte, dándole a la madre o cuidador sorbos de SRO frecuentemente durante el trayecto si el niño lo puede tolerar, en lugar de iniciar el Plan C en el establecimiento. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Deshidratación grave, p. 8.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('2ceb9585-13b2-5e12-9f34-490ce4ff276e', 'Caso clínico: Un lactante de 2 meses presenta fiebre de 38.2°C axilar y rigidez de nuca. ¿Cuál es la clasificación correcta según el cuadro de fiebre?', 'Dengue sin signos de alarma; manejo ambulatorio', 'Fiebre simple; paracetamol y seguimiento en 3 días', 'Malaria; tratamiento antimalárico completo', 'Enfermedad febril muy grave; primera dosis de antibiótico apropiado y referencia urgente', 'D', 'La rigidez de nuca es, por sí sola, uno de los signos que clasifican como Enfermedad febril muy grave según el cuadro de la página 9. Además, en menores de 3 meses con fiebre ≥38°C también se clasifica en esta categoría. La conducta es dar la primera dosis de un antibiótico apropiado, paracetamol si la fiebre es >38.5°C, y referir urgente al hospital. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, 4. ¿Tiene la niña o niño fiebre?, cuadro Enfermedad febril muy grave, p. 9.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('2cec9bae-7006-5400-bbea-df4355a97ad1', 'Caso clínico: Una niña de 4 años que vive en zona de riesgo de dengue presenta fiebre de 3 días y hoy inicia con dolor abdominal intenso y continuo, y vómito persistente. ¿Cuál es la clasificación correcta según la guía?', 'Dengue con signos de alarma (DCSA); hidratación IV según plan de hidratación de dengue y referencia urgente', 'Dengue sin signos de alarma; manejo ambulatorio con paracetamol', 'Malaria; antimalárico oral', 'Dengue grave; requiere signos de choque o hemorragia masiva', 'A', 'El dolor abdominal intenso y continuo y el vómito persistente son signos de alarma listados en el cuadro de la página 9, que clasifican como Dengue con signos de alarma (DCSA). La conducta es iniciar hidratación IV según el plan de hidratación de dengue, notificar de inmediato a epidemiología y referir urgente al hospital acompañado de personal de salud. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, 4. ¿Tiene la niña o niño fiebre?, cuadro Dengue con signos de alarma (DCSA), p. 9.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('c432c6da-5280-5588-8ba3-5c33d265e863', 'Según la guía, ¿cuál de los siguientes medicamentos NO debe usarse en el manejo de un niño con Dengue sin signos de alarma?', 'Paracetamol', 'Ibuprofeno o diclofenaco', 'Suero oral / líquidos abundantes', 'Ninguno de los anteriores está contraindicado', 'B', 'La guía explica claramente que en el manejo del Dengue sin signos de alarma (DSSA) o chikungunya se debe explicar la importancia de NO usar antiinflamatorios no esteroideos como ibuprofeno o diclofenaco, ni medicamentos por vía IM o rectal, ni corticoides ni antibióticos, debido al riesgo de sangrado asociado. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Dengue sin signos de alarma (DSSA) o Chikungunya, p. 9.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('2f45be57-920d-5df2-bb1b-8021157835e6', 'Caso clínico: Un niño de 3 años presenta erupción cutánea generalizada de inicio cefalocaudal, sin vesículas, acompañada de tos y ojos enrojecidos. ¿Cuál es la clasificación y una de las conductas correctas?', 'Dengue sin signos de alarma; reposo y mosquitero', 'Otra enfermedad eruptiva; paracetamol solamente', 'Sospecha de sarampión; dar vitamina A (salvo megadosis reciente) y notificar el caso a la unidad de epidemiología', 'Faringoamigdalitis viral; remedio casero', 'C', 'La erupción cutánea generalizada de progresión cefalocaudal, no vesicular, acompañada de tos, catarro u ojos enrojecidos clasifica como Sospecha de sarampión. La conducta incluye dar vitamina A (p.28) excepto si ya recibió una megadosis en el último mes, dar paracetamol si la fiebre es alta, y notificar el caso a la unidad de epidemiología correspondiente. Referencia: ¿Tiene la niña o niño fiebre? (seguimiento del cuadro anterior), Determinar si tiene enfermedad eruptiva, cuadro Sospecha de sarampión, p. 10.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('5905cc89-93d1-5c7c-85e4-925bca6d6fb0', 'Caso clínico: Un niño de 4 años que vive en zona de alto riesgo de malaria presenta fiebre sin causa aparente y una gota gruesa positiva, sin signos de enfermedad febril muy grave. ¿Cuál es la clasificación y la conducta correcta?', 'Fiebre; paracetamol únicamente sin tratamiento específico', 'Enfermedad febril muy grave; antibiótico y referencia urgente', 'Dengue grave; hidratación IV', 'Malaria; notificación del caso, tratamiento antimalárico completo y seguimiento en 3 días si la fiebre persiste', 'D', 'Vivir en zona de alto riesgo de malaria, sin signos de enfermedad febril muy grave, con gota gruesa positiva, clasifica como Malaria. La conducta incluye llenar el formulario de notificación, dar el tratamiento antimalárico completo indicado en la guía, y hacer seguimiento en el establecimiento de salud a los 3 días si la fiebre persiste. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Malaria, p. 9.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('b8e1dbd6-e1ff-5282-b822-5ebabab79b50', 'En el seguimiento de un niño clasificado como Fiebre (sin causa aparente identificada), si la fiebre persiste desde hace 7 días o más, ¿cuál es la conducta indicada?', 'REFERIR al hospital para evaluación y tratamiento', 'Continuar solo con paracetamol sin exámenes adicionales', 'Clasificar automáticamente como malaria', 'Suspender el seguimiento porque ya se cumplió el plazo de control', 'A', 'La guía indica que en el seguimiento de fiebre sin causa aparente, si esta persiste desde hace 5 días se debe realizar hemograma y examen de orina (si no es posible, referir), y si la fiebre persiste desde hace siete días o más, se debe REFERIR al hospital para evaluación y tratamiento. Referencia: Proporcionar atención de reevaluación y seguimiento, Fiebre, si la fiebre persiste después de 3 días, p. 31.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('2ff2171c-a968-56a1-b348-7d70de652de0', 'Caso clínico: Una niña de 3 años presenta tumefacción dolorosa al tacto detrás de la oreja. ¿Cuál es la clasificación correcta y la conducta inmediata?', 'Otitis media aguda; antibiótico oral por 5 días', 'Mastoiditis; primera dosis de antibiótico apropiado, primera dosis de paracetamol para el dolor y referencia urgente al hospital', 'Otitis media crónica; gotas de ciprofloxacina', 'No tiene otitis media; observación en casa', 'B', 'La tumefacción dolorosa al tacto detrás de la oreja es el signo característico de Mastoiditis según el cuadro de problema de oído (p.11). La conducta es dar la primera dosis de un antibiótico apropiado, la primera dosis de paracetamol para el dolor y referir URGENTE al hospital. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, 5. ¿Tiene la niña o niño un problema de oído?, cuadro Mastoiditis, p. 11.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('5996bdd3-2744-588d-9995-825d3d3e482f', 'Según la nota de la guía sobre otitis media aguda, ¿en qué condición se puede proponer a los padres un tratamiento diferido (antibiótico solo si no mejora tras 3 días)?', 'Únicamente si tiene menos de 6 meses de edad', 'En cualquier niño con otitis media aguda, sin excepción', 'Si la niña o niño es mayor de 2 años, no se ve muy enferma, no está desnutrida, no tiene otitis bilateral con secreción, y no nació prematura', 'Solo si presenta fiebre alta persistente', 'C', 'La nota al pie del cuadro de problema de oído especifica que si la niña o niño es mayor de 2 años, no se ve muy enferma, no está desnutrida, no tiene otitis bilateral con secreción del oído y no nació prematura o antes de tiempo, puede proponerse a los padres la aplicación de un tratamiento diferido, recetando antibióticos solamente si no mejora después de 3 días. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, nota al pie del cuadro de problema de oído, p. 11.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('0cd7b5df-801c-5aeb-b470-7ced19b041f1', '¿Cuál es el esquema correcto de gotas de ciprofloxacina para el tratamiento de la otitis media crónica según la guía?', '2 gotas dos veces al día por 7 días', '1 gota una vez al día por 5 días', '5 gotas cuatro veces al día por 21 días', '3 gotas tres veces al día por 14 días, luego de asear cuidadosamente el oído', 'D', 'La guía indica que para la otitis media crónica se deben aplicar gotas de ciprofloxacina, 3 gotas tres veces al día durante 14 días, después del aseo cuidadoso del oído; si deja de supurar se puede interrumpir el tratamiento a los 7 días. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, cuadro Otitis media crónica, p. 11.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('3bbdb2a5-ca1a-5a31-83e3-1e6c0dd0142a', 'Caso clínico: Un niño de 4 años presenta fiebre de 38.5 °C, amígdalas eritematosas con exudado purulento, ganglios cervicales anteriores crecidos y dolorosos, y ausencia de tos. ¿Cuál es la clasificación correcta y el objetivo principal del tratamiento antibiótico según la guía?', 'Faringoamigdalitis estreptocócica; el antibiótico busca prevenir complicaciones como la fiebre reumática, no solo calmar molestias', 'Faringoamigdalitis viral; el antibiótico no es necesario', 'No tiene faringoamigdalitis; investigar otras causas', 'Mastoiditis; referir urgente', 'A', 'El cumplimiento de las cuatro características (edad de 3 años o más, fiebre >38°C, amígdalas eritematosas con exudado, ganglios cervicales anteriores crecidos y dolorosos, y ausencia de tos) clasifica como Faringoamigdalitis estreptocócica. La guía explica que se debe dar un antibiótico apropiado, explicando a la familia que el objetivo del antibiótico no es calmar las molestias sino prevenir complicaciones como la fiebre reumática. Referencia: Evaluar y clasificar la niña o niño de 2 meses a menor de 5 años, 6. ¿Tiene la niña o niño un problema de garganta?, cuadro Faringoamigdalitis estreptocócica, p. 11.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('9e5cc146-4fb1-5a89-b7ce-09b56d221bf7', 'Caso clínico: Una niña de 8 meses presenta edema en ambos pies y peso menor a 4 kg. ¿Cuál es la clasificación y conducta correspondiente?', 'Desnutrición aguda moderada; ATLU ambulatorio', 'Desnutrición aguda severa con complicación; notificación, vitamina A, primera dosis de antibiótico apropiado y referencia urgente', 'No tiene desnutrición aguda; felicitar a la madre', 'Riesgo de sobrepeso; consejería nutricional', 'B', 'El edema en ambos pies es, por sí solo, criterio de desnutrición aguda; combinado con el peso menor de 4 kg (uno de los criterios de complicación), la niña se clasifica como Desnutrición aguda severa con complicación. La conducta es llenar el formulario de notificación antes de referir, dar vitamina A (salvo megadosis reciente), dar la primera dosis de un antibiótico apropiado y referir URGENTE al hospital. Referencia: Enseguida verificar crecimiento de la niña o niño, 7.1 Evaluar si presenta desnutrición aguda o sobrepeso, cuadro Desnutrición aguda severa con complicación, p. 12.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('ed4b2b71-2b30-5c23-ac36-2205eb72a331', 'Caso clínico: Un niño de 20 meses tiene un punto peso/talla que cae entre las curvas -2 DE y -3 DE (incluye -3DE) según su sexo, sin edema. ¿Cuál es la clasificación correcta?', 'No tiene desnutrición aguda', 'Desnutrición aguda severa sin complicación', 'Desnutrición aguda moderada', 'Talla baja', 'C', 'Según el cuadro de la página 12, un punto de peso/longitud o talla que cae entre la curva -2 DE hasta la -3 DE (incluyendo el punto que cae exactamente en la curva -3 DE) según el sexo, corresponde a la clasificación Desnutrición aguda moderada. Referencia: Enseguida verificar crecimiento de la niña o niño, cuadro Desnutrición aguda moderada, p. 12.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('b67152c4-1f43-51a1-8494-a2a4de3b5951', 'Caso clínico: Un niño de 10 meses tiene un punto de longitud/edad que cae por debajo de la curva -2 DE según su sexo. ¿Cuál es la clasificación y una de las conductas indicadas, considerando su edad?', 'Tendencia de crecimiento apropiada; continuar controles regulares', 'No tiene talla baja; felicitar a la madre', 'Desnutrición aguda severa; referir urgente', 'Talla baja; si tiene entre 6 y 23 meses, dar zinc durante 12 semanas y evaluar la alimentación', 'D', 'El punto de longitud o talla/edad por debajo de la curva -2 DE según el sexo clasifica como Talla baja. Dado que el niño tiene 10 meses (dentro del rango de 6 a 23 meses), la conducta incluye dar zinc durante 12 semanas (p.23), evaluar la lactancia materna o la alimentación y corregir los problemas identificados, y dar recomendaciones nutricionales según la edad. Referencia: Enseguida verificar crecimiento de la niña o niño, 7.2 Evaluar longitud o talla y tendencia de crecimiento, cuadro Talla baja, p. 13.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('ca891a11-5c0f-5ce5-be7f-bc894387644e', 'Según la guía, si una niña o niño presenta una tendencia de crecimiento inadecuada durante dos meses seguidos, ¿qué exámenes se deben indicar antes de referir con pediatra o nutricionista?', 'Hematocrito, hemoglobina, y elemental y microscópico de orina', 'Radiografía de tórax y electrocardiograma', 'Prueba de VIH y hepatitis B', 'Gota gruesa y prueba de diagnóstico rápido de dengue', 'A', 'La guía indica que si la niña o niño tiene tendencia de crecimiento inadecuado durante dos meses seguidos, se debe indicar hematocrito, hemoglobina, y elemental y microscópico de orina, y luego referir con pediatra o nutricionista. Referencia: Enseguida verificar crecimiento de la niña o niño, cuadro Tendencia de crecimiento inapropiada, p. 13.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('a9610aa7-9d15-5edd-94d8-593e95721998', 'Caso clínico: Un niño de 2 años presenta palidez palmar intensa. Su hemoglobina corregida por altitud es de 6.5 g/dL. ¿Cuál es la clasificación y conducta correspondiente?', 'Anemia leve; suplemento de hierro', 'Anemia grave; REFERIR urgente al hospital', 'Anemia moderada; consejería nutricional y hierro por 3 meses', 'No tiene anemia; felicitar a la madre', 'B', 'La palidez palmar intensa o una hemoglobina menor de 7 g/dL clasifican como Anemia grave según el cuadro de la página 14. La conducta es REFERIR urgente al hospital aplicando las recomendaciones para el transporte REFIERA. Referencia: Enseguida evaluar si tiene anemia, cuadro Anemia grave, p. 14.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('15c8b910-175f-55a1-a200-773a0f4c1fbc', 'Caso clínico: En un establecimiento de salud ubicado a 2700 metros sobre el nivel del mar, se mide una hemoglobina de 12.3 g/dL en un niño. Según la tabla de ajuste por altitud de la guía, ¿cuál es la hemoglobina corregida por altitud?', '10.5 g/dL', '12.3 g/dL (no requiere ajuste)', '11.0 g/dL', '13.1 g/dL', 'C', 'Según la tabla de ajuste de la guía, a una altitud de 2500-2999 metros sobre el nivel del mar se debe restar 1.3 g/dL al valor medido de hemoglobina. Por lo tanto, 12.3 g/dL menos 1.3 g/dL equivale a una hemoglobina real corregida de 11.0 g/dL. Referencia: Enseguida evaluar si tiene anemia, tabla de ajustes de las concentraciones de hemoglobina en función de la altitud, p. 14.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('f2256073-2f36-5348-b6f1-26817b435c73', 'Según el esquema de suplementación preventiva para prevención de la anemia, ¿cuál es la conducta correcta en una niña de 6 meses a 23 meses de edad, nacida a término con peso adecuado, cuando los sobres de micronutrientes en polvo están disponibles?', '2 sobres de micronutrientes en polvo diarios por 3 meses', 'Sulfato ferroso 8 gotas al día de forma continua', 'Vitamina A cada mes', '1 sobre de micronutrientes en polvo pasando un día, por 6 meses consecutivos o hasta completar 90 sobres', 'D', 'Para la prevención de la anemia en niñas y niños de 4 a 23 meses nacidos a término con peso adecuado al nacer, de 6 a 23 meses se indica 1 sobre de micronutrientes en polvo pasando un día, por 6 meses consecutivos o hasta completar 90 sobres en total. Referencia: Suplementación con micronutrientes: suplementación preventiva y terapéutica, Suplementación para prevención de la anemia, p. 28.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('8ec33aab-477b-555f-8965-741d94936ddc', 'Caso clínico: Un niño de 3 años presenta una fractura en el húmero y marcas compatibles con mordedura humana. ¿Cuál es la clasificación y la conducta indicada?', 'Compatible con maltrato físico y/o abuso sexual; tratar las lesiones, referir urgente al hospital, notificar a la autoridad competente y coordinar con protección de menores', 'Sospecha de maltrato físico o psicológico; seguimiento en 14 días', 'No hay sospecha de maltrato; recordar próxima visita de crecimiento', 'Falla en la crianza; reforzar habilidades parentales', 'A', 'Las fracturas de una o más extremidades y las marcas de mordedura humana son criterios explícitos que clasifican como Compatible con maltrato físico y/o abuso sexual. La conducta indicada es tratar las lesiones, referir URGENTE al hospital, llenar la ficha de notificación y referencia, y notificar a la autoridad competente coordinando con los equipos de protección de menores. Referencia: Evaluar maltrato infantil (físico y/o psicológico) y abuso sexual en niñas y niños menores de 5 años, cuadro Compatible con maltrato físico y/o abuso sexual, p. 15.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('93b45b5a-2eba-58b6-aec0-7eb23c1669c7', 'Según la guía, la clasificación ''Sospecha de maltrato infantil'' es considerada transitoria. ¿Cuáles son los dos momentos de seguimiento que deben realizarse tras esta clasificación?', 'Solo una consulta de seguimiento a los 30 días', 'Una visita domiciliaria en los primeros 3 días y una consulta de seguimiento a los 14 días', 'Una llamada telefónica semanal durante un mes', 'Referencia inmediata al hospital sin seguimiento posterior', 'B', 'La guía especifica que ante la clasificación de sospecha de maltrato infantil se debe realizar una visita domiciliaria durante los primeros 3 días de la evaluación inicial, y una consulta de seguimiento a los 14 días de dicha evaluación, con el objetivo de determinar si el caso debe reclasificarse como compatible con maltrato o como ''no hay sospecha de maltrato''. Referencia: Proporcionar atención de reevaluación y seguimiento, Seguimiento a la clasificación ''sospecha de maltrato infantil'', p. 33.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('9feb14da-a83e-532c-ab0c-1a2b3804fb11', 'Caso clínico: Un niño de 14 meses no ha alcanzado ninguno de los hitos correspondientes al grupo de edad de 9 a 12 meses (el grupo de edad anterior al suyo). ¿Cuál es la clasificación correcta?', 'Alerta para el desarrollo psicomotor', 'Desarrollo psicomotor normal', 'Probable retraso del desarrollo psicomotor', 'Desarrollo psicomotor normal con factores de riesgo', 'C', 'Según el cuadro de desarrollo psicomotor (p.16), la ausencia de uno o más hitos del grupo de edad anterior al de la niña o niño clasifica como Probable retraso del desarrollo psicomotor, lo cual exige referencia para evaluación por médica o médico pediatra. Referencia: 12. Evaluar el desarrollo psicomotor, cuadro Probable retraso del desarrollo psicomotor, p. 16.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('a0b16eac-16ad-5b72-90e8-4633ca311614', 'Caso clínico: Una niña de 12 meses acude a control de vacunas. Según el cronograma de vacunación 2017 de la guía, ¿qué vacunas corresponden a esta edad?', 'Varicela', 'BCG y HB', 'OPV3, Pentavalente3 y Neumococo conjugado3', 'SRP1 y Fiebre amarilla', 'D', 'Según el cronograma de vacunación 2017, a los 12 meses corresponde aplicar la primera dosis de SRP (sarampión, rubeola y parotiditis) y la vacuna contra la Fiebre amarilla. Referencia: 13. Enseguida verificar esquema de vacunación de la niña o niño, cronograma de vacunación 2017, p. 16.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('4a32483a-b0ed-53d6-be9e-3250fd8c3561', 'Caso clínico: Un niño de 2 años tiene dientes sin caries, pero se observa placa blanquecina adherida a las piezas dentales y la madre refiere que usa biberón frecuentemente. ¿Cuál es la clasificación correcta según el cuadro de salud oral?', 'Dientes sanos con riesgo de caries; dar recomendaciones para la salud bucal y referir al odontólogo', 'Caries dentales; referir al odontólogo', 'Dientes sanos sin riesgo de caries; felicitar a la madre', 'No aplica clasificación en menores de 3 años', 'A', 'La presencia de placa bacteriana adherida a la pieza dental (sin cavitación ni mancha) junto con el uso de biberón corresponde a la clasificación Dientes sanos con riesgo de caries, según el cuadro de la página 18. La conducta es dar recomendaciones para la salud bucal e indicar la importancia de su aplicación para prevenir las caries, además de referir al odontólogo más cercano. Referencia: 14. Evaluar la salud oral de la niña o niño, cuadro Dientes sanos con riesgo de caries, p. 18.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('ddd3500d-6fe5-5b89-b294-1f52046cb002', 'Según las recomendaciones de alimentación de la guía, ¿hasta qué edad se recomienda la lactancia materna exclusiva, sin ningún otro alimento o líquido, ni siquiera agua?', 'Hasta los 4 meses de edad', 'Hasta los 6 meses de edad', 'Hasta el año de edad', 'Hasta los 8 meses de edad', 'B', 'La guía indica que hasta los 6 meses de edad se debe dar lactancia materna exclusiva, sin agregar ninguna otra comida ni líquidos, explicando explícitamente que el niño no necesita tomar agua porque la leche materna contiene suficiente agua. Referencia: Recomendaciones para la alimentación de la niña o niño sano o enfermo según la edad, Hasta los 6 meses de edad, p. 35.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('fe2cb52d-c3be-5f3e-a086-cc52cce6fd0b', 'Según la guía, ¿cuál es la forma correcta de iniciar la alimentación complementaria en una niña o niño de 6 a 8 meses?', 'Introducir varios alimentos nuevos al mismo tiempo para acelerar la adaptación', 'Iniciar directamente con alimentos licuados muy diluidos para facilitar la deglución', 'Comenzar con 2 a 3 cucharadas de alimentos bien aplastados con tenedor (no licuados), formando una papilla espesa', 'Ofrecer únicamente jugos de fruta colados', 'C', 'La guía recomienda comenzar con 2 a 3 cucharadas de alimentos bien aplastados con tenedor (no licuados), de modo que formen una papilla espesa, introduciendo cada alimento nuevo por separado y permitiendo que el niño lo pruebe por 3 días antes de introducir otro. Referencia: Recomendaciones para la alimentación de la niña o niño sano o enfermo según la edad, 6 a 8 meses, p. 35.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('e8f6a3f7-3b12-5d1a-92e6-475e52f471f5', 'Según la orientación de la guía para investigar las causas de la desnutrición, si la dieta de la niña o niño es mayoritariamente a base de cereal, ¿qué se debe recomendar a la madre o cuidador?', 'Sustituir el cereal únicamente por frutas', 'Diluir más el cereal para facilitar la digestión', 'Eliminar completamente el cereal de la dieta', 'Prepararlo más espeso, no diluido, y agregar un poco de grasa (como aceite) para aumentar la densidad energética', 'D', 'La guía indica que si la dieta es mayormente a base de cereal, se debe motivar a la madre o cuidador a prepararlo más espeso, no diluido, y agregar un poco de grasa (como aceite) para aumentar la densidad energética del alimento. Referencia: Investigar las causas de la desnutrición o crecimiento inadecuado y aconsejar, punto 4, p. 40.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('f24665b0-2049-578e-a120-f35293dc1f49', 'Según la guía sobre investigación de causas del sobrepeso y obesidad, si una niña o niño menor de 6 meses NO recibe lactancia materna, ¿cuál es la cantidad diaria de fórmula suficiente entre 0 y 1 mes de edad?', '480 mL (16 onzas) al día', '250 mL (8 onzas) al día', '900 mL (30 onzas) al día', '1200 mL (40 onzas) al día', 'A', 'La guía especifica que si el niño no recibe lactancia materna, entre 0 y 1 mes de edad debe recibir 480 mL (16 onzas) de fórmula al día, cantidad que se ajusta progresivamente hasta 630 mL entre 1-2 meses, 720 mL entre 2-3 meses y 900 mL entre 4-6 meses. Referencia: Investigar las causas del sobrepeso y obesidad y aconsejar, cuadro si la niña o niño es menor de 6 meses, p. 41.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('275231ab-7570-5dc4-b13f-4de095d87040', 'Caso clínico: Un niño de 4 años tiene un punto de peso/talla que cae por encima de la curva +2 DE hasta la curva +3 DE (incluyendo el punto que cae en +3 DE) según su sexo. ¿Cuál es la clasificación correcta?', 'Riesgo de sobrepeso', 'Sobrepeso', 'Obesidad', 'Rango normal', 'B', 'Según el cuadro de la página 12, un punto de peso/longitud o talla por encima de la curva +2 DE hasta la curva +3 DE (incluyendo el que cae en +3 DE) corresponde a la clasificación Sobrepeso. Referencia: Enseguida verificar crecimiento de la niña o niño, cuadro Sobrepeso, p. 12.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('d1913df3-dad0-5f76-b35e-30f1d303cd30', 'Según la guía, ¿cuáles son hitos de desarrollo esperados entre los 12 y 15 meses de edad?', 'Copia un círculo y salta en un solo pie', 'Sostiene la cabeza y sigue objetos con la mirada', 'Imita gestos, agarra objetos pequeños con el pulgar y el índice, conversa en su ''idioma'' (lenguaje bebé), y camina con apoyo', 'Se viste sin ayuda y comprende 4 preposiciones', 'C', 'Según el listado de hitos de desarrollo de la guía, entre los 12 y 15 meses se espera que la niña o niño imite gestos, agarre objetos pequeños con el pulgar y el índice, converse en su ''idioma'' (lenguaje bebé) y camine con apoyo. Referencia: Determinar hitos de desarrollo, grupo 12 a 15 meses, p. 17.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('0cba7a07-5942-5e0e-b7ee-3ce3d70c6c69', 'Según la guía, ¿qué antibiótico oral se administra a una niña o niño clasificado como Desnutrición aguda severa sin complicación, y por cuántos días?', 'Cefalexina por 7 días', 'Ciprofloxacina por 3 días', 'Azitromicina por 10 días', 'Amoxicilina por 5 días', 'D', 'El cuadro de Desnutrición aguda severa sin complicación indica que se debe dar amoxicilina por 5 días, además del manejo multidisciplinario, la notificación, la administración de ATLU, y la investigación de las causas de la desnutrición. Referencia: Enseguida verificar crecimiento de la niña o niño, cuadro Desnutrición aguda severa sin complicación, p. 12.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('77930851-8de8-5e56-91e3-559947b0be8c', 'Caso clínico: Un lactante de 4 meses de edad presenta palidez palmar leve y hemoglobina corregida de 9 g/dL. En el establecimiento de salud no hay sobres de micronutrientes en polvo disponibles. ¿Cuál es la clasificación y el manejo del hierro correspondiente?', 'Anemia moderada; administrar hierro en gotero o jarabe por 3 meses', 'Anemia leve; solo suplementación preventiva', 'Anemia grave; referir urgente', 'No tiene anemia; no requiere hierro', 'A', 'La palidez palmar leve o hemoglobina entre 7 y 9.9 g/dL clasifican como Anemia moderada. Como el lactante tiene 4 meses (fuera del rango de 6-23 meses para el uso de sobres de micronutrientes) y además éstos no están disponibles, se administra hierro en forma de gotero o jarabe durante 3 meses, con consejería nutricional y control de adherencia a los 14 días. Referencia: Enseguida evaluar si tiene anemia, cuadro Anemia moderada, p. 14.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('0c2e206b-9e64-5392-8e04-5889eff2e3f9', 'Según la guía, ¿cuántos criterios positivos son necesarios para considerar que una niña o niño tiene riesgo social?', 'Es necesario que se cumplan al menos 3 criterios', 'Con un solo criterio positivo ya debe considerarse con riesgo social', 'Se requieren todos los criterios de la lista', 'El riesgo social solo se determina si hay antecedente de muerte de un hermano', 'B', 'La guía establece de forma explícita en la interpretación del cuadro de riesgo social que con un solo criterio positivo que cumpla la niña o niño, debe ser considerado con riesgo social, requiriendo observación en el establecimiento de salud, visita domiciliaria o ingreso hospitalario según corresponda. Referencia: Evaluación del riesgo social, Interpretación, p. 90.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('db1909b8-d455-590e-a034-0b34ce78eeb1', 'Caso clínico: Un niño de 8 meses, con desnutrición aguda severa, pesa 6 kg. Se le realiza la prueba del apetito con un sobre de ATLU. Según la tabla de criterios de evaluación de la prueba del apetito, ¿qué consumo mínimo del sobre se considera positivo para este peso?', 'Consumo mínimo mayor a 1/2 del sobre', 'Consumo mínimo mayor a 1/3 del sobre', 'Consumo mínimo mayor a 1/4 del sobre', 'Debe consumir el sobre completo', 'C', 'Según la tabla de criterios de evaluación de la prueba del apetito, para niñas y niños de 6 a 59 meses con peso de 4 a 6.9 kg, se considera positiva la prueba si el consumo mínimo de ATLU es mayor a 1/4 del sobre. Referencia: El Alimento Terapéutico Listo para su Uso (ATLU), Criterios para la evaluación de la prueba del apetito, p. 91.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('35b28b12-2b0b-5c7b-95c7-008eb0a12577', 'Según la guía, ¿en cuál de las siguientes situaciones NO se debe realizar la prueba del apetito con ATLU y se debe remitir directamente al manejo intrahospitalario?', 'En un niño con desnutrición aguda moderada de 18 meses', 'En un niño de 2 años con desnutrición aguda severa sin complicaciones', 'En un niño de 3 años con buen apetito', 'En un lactante menor de 6 meses o con peso menor de 4 kg', 'D', 'La guía indica de forma explícita que en menores de 6 meses o con peso menor de 4 kg NO se debe realizar la prueba del apetito, y se debe remitir directamente al manejo intrahospitalario, ya que estas son contraindicaciones para realizar dicha prueba. Referencia: El Alimento Terapéutico Listo para su Uso (ATLU), Contraindicaciones para realizar la prueba del apetito, p. 91.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('50a8954a-dd6b-5c37-a263-9cf41a61586b', 'Según el algoritmo de tamizaje para cardiopatías, si al colocar el oxímetro de pulso en la mano derecha o el pie se obtiene una saturación de oxígeno menor de 92%, ¿cuál es la conducta correcta?', 'Es positivo inmediato; referir al hospital al cardiólogo pediatra o buscar la causa de hipoxemia', 'Repetir la prueba en 1 hora', 'Dar de alta sin más evaluación', 'Realizar la prueba nuevamente a los 7 días', 'A', 'Según el algoritmo de tamizaje para cardiopatías, una saturación de oxígeno menor de 92% en mano derecha o pie se considera un resultado ''positivo inmediato'', cuya conducta es referir al hospital al cardiólogo pediatra o buscar la causa de la hipoxemia. Referencia: Tamizaje para cardiopatías, algoritmo, p. 92.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('eebc9888-8d36-5615-a913-93cfe896a6f3', 'Según la tabla de interpretación de indicadores de la guía, ¿qué implica un retardo en la talla (talla baja) para el riesgo de sobrepeso, de acuerdo con la nota explicativa?', 'No tiene ninguna relación con el sobrepeso', 'Una niña o niño con retardo en talla, baja talla o baja talla severa puede desarrollar sobrepeso', 'Protege completamente contra el desarrollo de sobrepeso', 'Solo ocurre en niños obesos previamente', 'B', 'La nota 3 de la tabla de interpretación de indicadores especifica claramente que una niña o niño con retardo en talla, baja talla o baja talla severa PUEDE DESARROLLAR SOBREPESO, por lo que el seguimiento del crecimiento debe considerar ambos aspectos de forma conjunta. Referencia: Problemas de crecimiento en niñas y niños menores de 5 años, Interpretación de indicadores, nota 3, p. 86.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('270f0508-3d9e-5c60-b950-566a6e91a734', 'Según los patrones de crecimiento infantil de la OMS incluidos en la guía, ¿qué evalúa principalmente el indicador peso para la longitud?', 'El perímetro cefálico y el desarrollo cerebral', 'La desnutrición crónica o desmedro', 'La desnutrición aguda o emaciación, como medida del estado nutricional actual', 'La desnutrición global exclusivamente en mayores de 2 años', 'C', 'La guía explica que el indicador ''peso para la longitud'' evalúa la desnutrición aguda o emaciación, siendo una medida del estado nutricional actual; el bajo peso para la longitud generalmente resulta de una ingesta de alimentos insuficiente en períodos cortos y/o episodios repetidos de enfermedades agudas recientes, en especial diarrea. Referencia: Niñas: Curva de crecimiento peso/longitud (0 a 2 años), p. 74.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('6493afc9-6274-5eae-8fdf-aa9a4913e7e7', 'Según la guía, si la madre o cuidador está alimentando a la niña o niño con biberón, ¿cuál es la recomendación correcta?', 'No es necesario ningún cambio si el niño gana peso adecuadamente', 'Continuar con el biberón pero esterilizarlo con mayor frecuencia', 'Cambiar a un biberón de otro material', 'Recomendarle que use una taza y una cuchara en vez del biberón, y mostrarle cómo alimentar de esa manera', 'D', 'La guía indica que si la madre o cuidador está alimentando con biberón se le debe recomendar que use una taza y una cuchara en vez del biberón, y mostrarle cómo alimentar a la niña o niño con taza y cuchara, dado que el uso de biberón se asocia a mayor riesgo de infecciones y de caries. Referencia: Aconsejar a la madre o cuidador sobre problemas de alimentación, p. 36.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('02ec05ba-4a46-5c99-a813-3797fb43ff70', 'Caso clínico: Una gestante de 34 semanas presenta hemorragia vaginal y refiere disminución de los movimientos fetales. ¿Cuál es la clasificación correcta según el cuadro de determinación de riesgo durante el embarazo?', 'Embarazo con riesgo inminente o muy alto; estabilizar y tratar antes de referir urgente', 'Embarazo de bajo riesgo; control prenatal habitual', 'Embarazo de alto riesgo; solo asesoría nutricional', 'Amenaza de parto pretérmino; tocólisis únicamente', 'A', 'La hemorragia vaginal y la disminución de los movimientos fetales son signos que, cada uno por sí solo, clasifican como Embarazo con riesgo inminente o muy alto. La conducta es estabilizar y tratar antes de referir (prevenir hipotensión, tratar hemorragia según clave roja, administrar oxígeno si existe posibilidad) y referir URGENTE, acostada del lado izquierdo, al centro de mayor complejidad. Referencia: Determinar riesgo durante el embarazo, cuadro Embarazo con riesgo inminente o muy alto, p. 42.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('46aefa25-4890-5ca8-bd8f-2ea58fdabcab', 'Caso clínico: Una gestante con preeclampsia presenta presión arterial diastólica de 112 mmHg. Según el manejo de emergencia de la guía, ¿cuál es el fármaco de acción rápida de primera elección y su dosis inicial para reducir la presión arterial?', 'Sulfato de magnesio 10 mg IV', 'Nifedipina de acción rápida 10 mg VO cada 20-30 minutos según respuesta (dosis máxima total 60 mg)', 'Furosemida 20 mg IV', 'Metildopa 250 mg cada 8 horas', 'B', 'Ante una presión arterial diastólica ≥110 mmHg, la guía indica administrar un antihipertensivo de acción rápida: nifedipina 10 mg VO cada 20-30 minutos según respuesta, con una dosis máxima total de 60 mg, y luego 10-20 mg cada 6-8 horas VO (dosis máxima 120 mg en 24 horas). Referencia: Manejo de emergencia frente a complicaciones del embarazo, parto y postparto, Hipertensión grave, preeclampsia y eclampsia, p. 44.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('dfbd4d46-2c26-56c5-a37d-84111fcc6009', 'Según la guía, ¿cuál es el antídoto indicado ante sospecha de intoxicación por sulfato de magnesio (frecuencia respiratoria menor de 12/min, arreflexia, bradicardia o paro cardíaco)?', 'Sulfato de magnesio en dosis adicional', 'Naloxona IV', 'Gluconato de calcio al 10%, una ampolla de 1 g (10 mL) IV lento en 3 a 10 minutos', 'Bicarbonato de sodio IV', 'C', 'Ante sospecha clínica de intoxicación por sulfato de magnesio (frecuencia respiratoria <12/min, arreflexia, bradicardia o paro cardíaco), se debe descontinuar el sulfato de magnesio y administrar el antídoto: gluconato de calcio al 10%, una ampolla de 1 g (10 mL), por vía IV lento en 3 a 10 minutos, además de oxígeno y ventilación asistida si es necesario. Referencia: Manejo de emergencia frente a complicaciones del embarazo, parto y postparto, Intoxicación por sulfato de magnesio, p. 44.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('d565323d-955d-5e3d-ad29-b7fde65f5f44', 'Caso clínico: Una parturienta presenta menos de 3 contracciones en 10 minutos; el partograma indica que el parto no es inminente. Además, la edad gestacional es de 35 semanas. ¿Cuál es la clasificación correcta y la conducta indicada?', 'Parto inminente con alto riesgo perinatal; canalizar vía venosa y proceder al parto', 'Trabajo de parto con bajo riesgo perinatal; referir al establecimiento adecuado', 'Parto inminente con bajo riesgo perinatal; atender el parto según GPC', 'Trabajo de parto con alto riesgo perinatal; estabilizar y referir urgente al hospital', 'D', 'Menos de 3 contracciones en 10 minutos con parto no inminente según el partograma, junto con una edad gestacional menor de 37 semanas (parto prematuro), corresponden a los criterios de Trabajo de parto con alto riesgo perinatal. La conducta es estabilizar y referir URGENTE al hospital, incluyendo inhibir las contracciones con nifedipina y aplicar corticoide para maduración pulmonar si corresponde por edad gestacional. Referencia: Determinar riesgo durante el trabajo de parto y el parto, cuadro Trabajo de parto con alto riesgo perinatal, p. 43.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('5bf4bd84-4620-561f-b5cf-722fc1ce67fc', 'Caso clínico: Una gestante de 30 semanas presenta ruptura prematura de membranas, sin trabajo de parto activo. Según la guía, ¿cuál es el manejo antes de referir?', 'Iniciar maduración pulmonar fetal con dexametasona o betametasona, y administrar una dosis de ampicilina 2g IV o IM más eritromicina 250mg VO', 'Solo observación sin tratamiento farmacológico', 'Cesárea inmediata', 'Antibiótico oral únicamente, sin corticoide', 'A', 'Para un embarazo entre 24 y 34 semanas con 6 días con RPM, la guía indica iniciar la maduración pulmonar fetal (dexametasona 6mg IM cada 12h por 2 días o betametasona 12mg IM cada 24h por 2 días) y administrar una dosis de ampicilina 2g IV o IM más eritromicina 250mg VO, antes de referir. Referencia: Manejo de emergencia frente a complicaciones del embarazo, parto y postparto, Rotura prematura de membranas (RPM), p. 44.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('da57db5e-82b6-5ce8-a6fc-9230a2ff075f', 'Según la guía, ¿qué se entiende por ''el minuto de oro'' en la reanimación neonatal?', 'El primer minuto tras el pinzamiento del cordón umbilical', 'Los primeros 60 segundos tras el nacimiento, período crítico para lograr que el bebé respire y en el que se debe tomar la decisión de iniciar la ventilación', 'El minuto en que se administra la vacuna BCG', 'El tiempo que dura el apego piel a piel', 'B', '''El minuto de oro'' se refiere a los primeros 60 segundos tras el nacimiento, un período crítico durante el cual se debe determinar si el recién nacido respira adecuadamente y, de ser necesario, tomar la decisión de iniciar la ventilación a presión positiva antes de que transcurra ese minuto. Referencia: Plan de acción, ayudando a los bebés a respirar, ''El minuto de oro'', p. 46.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('fcf86fbe-7033-5220-aacb-5f187d895490', 'Según los puntos críticos de la reanimación neonatal básica, ¿cuál es la frecuencia de ventilación recomendada durante la ventilación a presión positiva?', '60 ventilaciones por minuto', '20 ventilaciones por minuto', '40 ventilaciones por minuto', '100 ventilaciones por minuto', 'C', 'La guía especifica en los puntos críticos para la reanimación neonatal básica que la frecuencia de ventilación es de 40 ventilaciones por minuto, cuidando que la mascarilla esté bien colocada y que la ventilación sea efectiva (el tórax debe elevarse/expandirse con cada ventilación). Referencia: Puntos críticos para la reanimación neonatal básica, p. 47.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('e11e57e8-1412-5d85-9ffb-35752bcf5cb5', 'Según la guía, ¿en qué momento se debe suspender la reanimación neonatal?', 'A los 5 minutos si la frecuencia cardíaca es menor de 100/min', 'A los 2 minutos de iniciada, independientemente de la respuesta', 'Nunca debe suspenderse la reanimación', 'Si después de 10 minutos de aplicación correcta de maniobras el bebé no respira y la frecuencia cardíaca es 0', 'D', 'La guía indica explícitamente que se debe suspender la reanimación neonatal si después de 10 minutos de aplicación correcta de las maniobras, el bebé no respira y su frecuencia cardíaca es 0. Referencia: Puntos críticos para la reanimación neonatal básica, p. 47.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('78b51ea3-0798-5020-aab8-dc9ed0274cc8', 'Según el método de Capurro descrito en la guía, ¿cuál es la fórmula utilizada para calcular la edad gestacional a partir del puntaje parcial obtenido de los signos físicos?', '(Puntaje parcial + 204) dividido entre 7', 'Puntaje parcial dividido entre 7', 'Puntaje parcial multiplicado por 204', '(Puntaje parcial - 204) dividido entre 7', 'A', 'El método de Capurro descrito en la guía indica que, tras sumar los puntajes de cada uno de los signos físicos (forma de la oreja, tamaño de la glándula mamaria, formación del pezón, textura de la piel y pliegues plantares), se aplica la fórmula: (Puntaje parcial + 204) dividido entre 7, para obtener las semanas de edad gestacional. Referencia: Valoración inicial de la recién nacida o recién nacido, Diagnóstico de edad gestacional (método de CAPURRO), p. 50.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('314d9410-a2a3-5d9a-848b-fdfe4ae5526c', 'Caso clínico: Un recién nacido presenta un puntaje total de 6 puntos en la escala de Silverman-Andersen. ¿Cómo se clasifica la dificultad respiratoria de este recién nacido?', 'Sin dificultad respiratoria', 'Dificultad respiratoria grave', 'Dificultad respiratoria leve', 'Dificultad respiratoria moderada', 'B', 'Según la interpretación de la puntuación de Silverman-Andersen descrita en la guía, un puntaje de 5 puntos o más se clasifica como Dificultad respiratoria grave. Al tener 6 puntos, el recién nacido de este caso se encuentra en esta categoría. Referencia: Valoración de la dificultad respiratoria (Silverman-Andersen), tabla de interpretación, p. 48.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('502fdfe3-712c-5c03-9d27-a4dce4e17ec5', 'Según la guía, ¿a partir de qué puntuación de Silverman-Andersen se debe administrar oxígeno a flujo libre al recién nacido con dificultad para respirar?', '2 puntos o más', '1 punto o más', '3 puntos o más', 'Únicamente con 5 puntos o más', 'C', 'La guía indica que se debe administrar oxígeno a flujo libre al recién nacido que presenta cianosis generalizada o dificultad para respirar de moderada a grave, definida como una puntuación de Silverman-Andersen igual o mayor a 3 puntos. Referencia: Oxigenoterapia, Cómo administrar oxígeno a flujo libre, p. 48.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('2c462ea5-3ed7-523b-9f0b-ba85e61351da', 'Caso clínico: Un recién nacido pesa 1800 gramos y presenta dificultad respiratoria moderada. ¿Cuál es la clasificación de la condición al nacer y una de las conductas indicadas?', 'Condición grave al nacer; bañarlo de inmediato y esperar 24 horas', 'Condición buena al nacer; alojamiento conjunto sin más medidas', 'Condición de cuidado al nacer; referir a consulta especializada', 'Condición grave al nacer; administrar oxígeno, primera dosis de antibióticos apropiados según criterio, y referir urgente al hospital', 'D', 'El peso menor de 2000 g y la dificultad respiratoria moderada son, cada uno, criterios que clasifican como Condición grave al nacer. La conducta incluye administrar oxígeno si hay dificultad respiratoria o cianosis, dar la primera dosis de antibióticos apropiados si corresponde (por ejemplo si es prematuro), verificar cumplimiento de cuidados rutinarios y referir URGENTE al hospital según las normas de estabilización y transporte REFIERA. Referencia: Procedimientos de atención inmediata a la recién nacida o recién nacido, Evaluar la condición al nacer, cuadro Condición grave al nacer, p. 49.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('28631a0a-36c6-50f2-8489-8041daf612ff', 'Según la guía, ¿cuál es la dosis de vitamina K que se debe administrar por vía intramuscular a un recién nacido prematuro (menor de 36 semanas de gestación) que pesa menos de 2.5 kg?', '0.4 mg/kg (dosis máxima 1 mg)', '1 mg fijo, igual que en el RN a término', '2 mg/kg sin límite máximo', 'No se administra vitamina K en prematuros', 'A', 'La guía especifica que en niñas y niños prematuros (menores de 36 semanas de gestación) que pesan menos de 2.5 kg se debe aplicar la dosis de 0.4 mg/kg de vitamina K, con una dosis máxima de 1 mg, por vía intramuscular en el tercio superior externo del muslo. Referencia: Cuidados esenciales de la recién nacida o recién nacido en el establecimiento de salud, nota (a), p. 51.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('c7a0b186-993e-50eb-9b67-9a3c53372add', 'Según la guía, ¿por qué es fundamental aplicar la vacuna contra la hepatitis B (HB) lo más pronto posible y antes de las 24 horas después del nacimiento?', 'Porque después de 24 horas la vacuna pierde su registro sanitario', 'Para proteger de manera efectiva contra una hepatitis transmitida por la madre', 'Porque coincide con el horario de administración de la BCG únicamente', 'No existe ninguna razón clínica específica, es solo un protocolo administrativo', 'B', 'La guía explica explícitamente en una nota que, para proteger de manera efectiva contra una hepatitis transmitida por la madre, la vacuna contra la hepatitis B (HB) debe aplicarse lo más pronto posible después del nacimiento, y antes de las 24 horas de vida. Referencia: Cuidados esenciales de la recién nacida o recién nacido en el establecimiento de salud, nota (b), p. 51; Vigilancia de la recién nacida o recién nacido, nota (a), p. 52.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('3d62896a-9f6c-58e8-aa86-230e03e9678e', 'Según la guía, ¿en qué momento se debe realizar el tamizaje metabólico neonatal (hipotiroidismo congénito, galactosemia, fenilcetonuria e hiperplasia suprarrenal congénita)?', 'Únicamente a los 3 meses de vida', 'Inmediatamente al nacer, antes de las 24 horas', 'A partir del 4to día y hasta el día 28 después del nacimiento', 'Solo si el recién nacido presenta ictericia', 'C', 'La guía especifica que el tamizaje metabólico se debe realizar a partir del 4to día y hasta el día 28 después del nacimiento, mediante la toma de una muestra de sangre del talón que se deposita en papel filtro. Referencia: Cuidados esenciales de la recién nacida o recién nacido en el establecimiento de salud, Tamizaje neonatal, Tamizaje metabólico, p. 51.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('e78cf889-f634-552b-bab3-54bdb826bfc8', 'Según la guía, ¿cuáles son signos de buen agarre al pecho materno?', 'El labio inferior está volteado hacia dentro', 'El recién nacido succiona rápido y de forma superficial, sin pausas', 'Se observa más areola por abajo que por arriba del pezón', 'El recién nacido toca la mama con el mentón, mantiene la boca bien abierta, el labio inferior volteado hacia fuera, y se observa más areola por arriba que por abajo', 'D', 'La guía enumera como signos de buen agarre: que el recién nacido toque la mama con el mentón, mantenga la boca bien abierta, el labio inferior volteado hacia fuera, y que se observe más areola por arriba que por abajo del pezón (agarre asimétrico). Referencia: Orientar a la madre sobre la lactancia materna inmediata y exclusiva, Enseñar los signos de buen agarre, p. 53.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('955a0f5d-1177-5a6e-8903-990bedbc7041', 'Según la guía, ¿cuál es la recomendación correcta para el cuidado del cordón umbilical en el hogar?', 'No colocar ninguna sustancia en el cordón umbilical (cremas, medicamentos, etc.) y mantenerlo libre con ropa suelta', 'Aplicar alcohol yodado diariamente', 'Cubrir el cordón con una faja apretada para acelerar la caída', 'Aplicar polvos antisépticos varias veces al día', 'A', 'La guía indica que no se debe colocar ninguna sustancia en el cordón umbilical (cremas, medicamentos, etc.), que se debe vestir al recién nacido con ropa suelta para que el cordón esté libre, y que si está sucio se debe lavar con agua limpia y jabón, secándolo cuidadosamente, sin usar apósitos, gasas, fajas ni polvos, ni cubrirlo con el pañal. Referencia: Orientar a la madre o acompañante sobre cuidados generales de la recién nacida o recién nacido (RN) en el hogar, Cuidar el cordón umbilical, p. 54.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('8b27ed8f-76b3-59f2-8f0d-6bc3013ce3ad', 'Según la guía, ¿en cuáles de las siguientes situaciones es especialmente recomendable la técnica canguro?', 'Únicamente en recién nacidos a término con peso mayor a 4000 g', 'En recién nacidos prematuros y como apoyo durante la referencia al hospital', 'Solo cuando la madre no puede amamantar', 'Únicamente durante el primer baño del recién nacido', 'B', 'La guía indica que la técnica canguro es ideal para evitar la hipotermia y es especialmente recomendable en el caso de recién nacidas/os prematuras/os y para la referencia al hospital, incentivando también la participación del padre u otro familiar en su aplicación en casa. Referencia: Orientar a la madre o acompañante sobre cuidados generales de la recién nacida o recién nacido (RN) en el hogar, Recomendaciones para la técnica canguro, p. 54.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('a32576cf-c0ee-5c80-a038-f685e47074c1', 'Según los cuidados ''extra'' para el recién nacido prematuro o con bajo peso al nacer, ¿desde qué edad y hasta cuándo se administra la solución de hierro en gotas, y a qué dosis?', 'Desde los 6 meses hasta el año de edad, a dosis de 1 mg/kg', 'Desde el nacimiento hasta el mes de edad, a dosis de 5 mg/kg', 'Desde los 28 días de nacido hasta los 6 meses de edad, a dosis de 2 mg/kg', 'No se recomienda hierro adicional en el prematuro', 'C', 'La guía indica administrar a diario solución de hierro en gotas a partir de los 28 días de nacido hasta los 6 meses de edad, a la dosis de 2 mg/kg, y que a partir de los 6 meses se debe suspender el hierro y administrar micronutrientes en polvo según el esquema correspondiente. Referencia: Cuidados ''extra'' en el hogar para una recién nacida o recién nacido prematura/o o con bajo peso al nacer, ''Extra'' suplementación de hierro, p. 55.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('cd67538f-50d6-5a5d-b4de-1a37a590440c', 'Según la guía, antes de dar de alta a la recién nacida o recién nacido, ¿qué se debe verificar obligatoriamente en relación con la vacunación?', 'No se requiere verificación de vacunas antes del alta', 'Que haya recibido la vacuna contra la influenza', 'Que haya recibido la vacuna SRP', 'Que haya recibido su vacuna BCG y HB', 'D', 'La guía indica explícitamente que antes de dar de alta a la recién nacida o recién nacido se debe verificar que haya recibido su vacuna BCG y HB (hepatitis B), dado que la efectividad de esta última depende de su aplicación antes de las 24 horas de vida. Referencia: Vigilancia de la recién nacida o recién nacido en el establecimiento de salud durante las primeras 24 horas de vida, p. 52.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('6c2c8c9a-eaa6-5b6c-af37-dc29cd1889db', 'Caso clínico: Un recién nacido de 10 días presenta temperatura axilar de 35.2°C y fontanela abombada. ¿Cuál es la clasificación y una de las conductas indicadas?', 'Enfermedad muy grave; primera dosis IM de los antibióticos recomendados y referencia urgente al hospital', 'Infección local; antibiótico oral por 5 días', 'No tiene enfermedad grave; solo lactancia exclusiva', 'Ictericia grave; fototerapia ambulatoria', 'A', 'La hipotermia (temperatura axilar <35.5°C) y la fontanela abombada son, cada una, criterios que clasifican como Enfermedad muy grave en el neonato o menor de 2 meses. La conducta incluye dar la primera dosis IM de los antibióticos recomendados (p.61), administrar oxígeno si hay dificultad respiratoria o cianosis, paracetamol si hay fiebre, y referir URGENTE al hospital según las normas REFIERA. Referencia: Atención al neonato o menor de 2 meses enfermo, 1. Evaluar si tiene enfermedad muy grave o infección local, cuadro Enfermedad muy grave, p. 56.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('c0e59904-81a8-5fcd-ad3f-d19174e83383', 'Caso clínico: Un lactante de 20 días presenta el ombligo eritematoso con secreción purulenta que no se extiende a la piel circundante, sin otros signos. ¿Cuál es la clasificación y el tratamiento correspondiente?', 'Enfermedad muy grave; referir urgente', 'Infección local; antibiótico oral por 5 días y enseñar a la madre a curar la infección local en casa', 'No tiene infección; solo observación', 'Ictericia; continuar lactancia exclusiva', 'B', 'El ombligo eritematoso o con secreción purulenta SIN extenderse a la piel es un criterio explícito de la clasificación Infección local. La conducta es dar un antibiótico oral por 5 días, enseñar a la madre a curar las infecciones locales en casa, aconsejar continuar la lactancia materna exclusiva y hacer seguimiento a los 2 días. Referencia: Atención al neonato o menor de 2 meses enfermo, cuadro Infección local, p. 56.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('9796da54-73f9-5dd3-9614-7af3fd227f0d', 'Caso clínico: Un recién nacido de 18 horas de vida presenta ictericia visible en cara y tronco. ¿Cuál es la clasificación correcta y la conducta indicada?', 'No tiene ictericia; alta con controles habituales', 'Ictericia; continuar lactancia y seguimiento en 1 día', 'Ictericia grave; REFERIR URGENTEMENTE al hospital', 'Infección local; antibiótico oral', 'C', 'Cualquier ictericia que aparezca en las primeras 24 horas de vida se clasifica como Ictericia grave, independientemente de su extensión, debido al riesgo de hiperbilirrubinemia patológica severa. La conducta es REFERIR URGENTEMENTE al hospital según las normas de estabilización y transporte. Referencia: Atención al neonato o menor de 2 meses enfermo, 2. Ictericia, cuadro Ictericia grave, p. 57.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('28bd9d56-d5f4-50f9-b634-5e4b9bb2bed0', 'Caso clínico: Un lactante de 6 semanas con diarrea presenta ojos hundidos y signo del pliegue cutáneo que regresa lentamente. ¿Cuál es la clasificación y la conducta correspondiente?', 'Diarrea con sangre; vitamina K', 'No tiene deshidratación; Plan A', 'Diarrea prolongada; solo seguimiento ambulatorio', 'Deshidratación; iniciar Plan B o C según corresponda, y referir URGENTE al hospital según las normas REFIERA', 'D', 'Dos de los signos siguientes —se mueve solo con estímulo o no se mueve del todo, inquieto/irritable, ojos hundidos, signo del pliegue cutáneo (regresa lenta o muy lentamente)— clasifican como Deshidratación en el menor de 2 meses. La conducta es dar líquidos para la deshidratación, iniciar el Plan B o C según corresponda, y referir URGENTE al hospital según las normas de estabilización y transporte REFIERA. Referencia: Atención al neonato o menor de 2 meses enfermo, 3. ¿Tiene la niña o niño diarrea?, cuadro Deshidratación, p. 57.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('0a6da786-ffc3-500e-9d88-553908c4247e', 'Caso clínico: Un recién nacido de 8 días ha perdido más del 10% de su peso desde el nacimiento y no succiona nada al pecho. ¿Cuál es la clasificación y la conducta correspondiente?', 'Problema grave de alimentación o peso bajo severo; primera dosis de antibióticos recomendados y referir urgente al hospital', 'Problemas de alimentación o peso bajo; control de peso cada 14 días', 'No tiene problema de alimentación; felicitar a la madre', 'Talla baja; suplementación con zinc', 'A', 'No succionar nada y presentar una pérdida de peso mayor al 10% en la primera semana son, cada uno, criterios de la clasificación Problema grave de alimentación o peso bajo severo. La conducta es dar la primera dosis de antibióticos recomendados (p.61), referir URGENTE al hospital según las normas REFIERA, y recomendar a la madre que continúe dándole el pecho. Referencia: Determinar si la niña o niño tiene problemas de alimentación o bajo peso, cuadro Problema grave de alimentación o peso bajo severo, p. 58.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('339a50bf-ec47-5b6e-bc40-75874bee621f', 'Según las normas de estabilización y transporte REFIERA, en la letra ''E'' de Energía=Glucosa, ¿cuál es la medida de emergencia que se puede aplicar cuando no hay posibilidad de canalizar una vía?', 'Inyectar glucosa hipertónica intramuscular', 'Colocar media cucharadita (2.5 g) de azúcar corriente humedecida debajo de la lengua del recién nacido, para absorción sublingual', 'Administrar únicamente agua limpia', 'Esperar hasta llegar al hospital de referencia sin intervención', 'B', 'La guía indica, dentro del componente E (Energía=Glucosa) de las normas REFIERA, que como medida de emergencia se puede colocar media cucharadita (2.5 g) de azúcar corriente humedecida debajo de la lengua del recién nacido, para su absorción sublingual, cuando no existe posibilidad de administrar líquidos por otra vía. Referencia: Normas de estabilización y transporte para la referencia (REFIERA), E: Energía = Glucosa, p. 60.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('5c36e7d9-6624-57ca-b658-3711ff446ad1', 'Caso clínico: Un recién nacido a término, en su primera semana de vida, con peso de 3 kg, requiere ampicilina y gentamicina IM antes de ser referido por Enfermedad muy grave. Según la tabla de dosificación, ¿cuál es la dosis correcta de gentamicina para este recién nacido?', '7.5 mg/kg, dosis para después de la primera semana de vida', '4 mg/kg, por ser prematuro', '5 mg/kg, dosis para el recién nacido a término en la primera semana de vida', '10 mg/kg sin distinción de edad', 'C', 'Según la tabla de dosificación de la guía, la dosis de gentamicina para la niña o niño a término durante la primera semana de vida es de 5 mg/kg, diferenciándose de la dosis de 4 mg/kg para el prematuro en su primera semana, y de 7.5 mg/kg para el recién nacido después de la primera semana de vida. Referencia: Tratar a la recién nacida o recién nacido y menores de 2 meses, tabla de dosificación de Gentamicina, p. 61.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('5699a58e-967f-5deb-960f-dd882da88342', 'Según la guía, ¿cuál es la frecuencia y duración del tratamiento con nistatina para la candidiasis oral (moniliasis) en el menor de 2 meses?', 'Solo una dosis única', 'Una vez al día por 3 días', 'Cada 12 horas por 10 días', 'Cada 6 horas por 5 a 7 días', 'D', 'La guía indica que la nistatina para el tratamiento de la candidiasis oral se administra con una frecuencia de cada 6 horas, durante 5 a 7 días, además de recomendar suspender el uso de chupones u objetos similares y limpiar la boca antes de aplicar el medicamento. Referencia: Tratar a neonatos y menores de 2 meses y aconsejar a los padres o cuidadores, tabla Nistatina, p. 62.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('215a6d01-db45-5dbb-af25-d22c44187862', 'Caso clínico: Un lactante de 5 semanas no presenta reflejo de succión ni reflejo de Moro. ¿Cuál es la clasificación correcta según el cuadro de desarrollo psicomotor para menores de 2 meses?', 'Probable retraso del desarrollo psicomotor; referir para evaluación especializada', 'Desarrollo psicomotor normal', 'Alerta para el desarrollo psicomotor', 'Desarrollo psicomotor normal con factores de riesgo', 'A', 'En el lactante de menos de 1 mes, la ausencia de uno o más hitos de su propio grupo de edad (como el reflejo de succión o el reflejo de Moro) clasifica como Probable retraso del desarrollo psicomotor, lo cual requiere referencia para una evaluación especializada. Referencia: 8. Determinar si la niña o niño tiene problemas de desarrollo psicomotor, cuadro Probable retraso del desarrollo psicomotor, p. 59.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('1b994b67-99bb-5a50-bde8-6e317439ac08', 'Según la nota de la guía sobre desarrollo psicomotor en el menor de 2 meses, ¿hasta qué edad debe considerarse la edad corregida en las niñas o niños prematuros al evaluar el desarrollo y el crecimiento?', 'Hasta los 6 meses de edad', 'Hasta los 12 meses de edad', 'Hasta los 24 meses de edad', 'Durante toda la vida', 'B', 'La guía indica que en niñas o niños prematuros se debe restar a la edad cronológica las semanas de gestación que no completó (dado que la gestación completa son 40 semanas), y que esta edad corregida debe considerarse hasta los 12 meses de edad al realizar la evaluación del desarrollo y el crecimiento. Referencia: 8. Determinar si la niña o niño tiene problemas de desarrollo psicomotor, NOTA sobre edad cronológica y edad corregida, p. 59.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('f6bc8062-7296-51b9-9826-c6828adb3d90', 'Según la guía, ¿cuál de las siguientes condiciones se considera un riesgo neurológico que debe ser referido para tratamiento especializado durante el seguimiento del neonato y menor de 2 meses?', 'Lactante que duerme más de 16 horas al día', 'Recién nacido con peso mayor a 3500 g sin otros antecedentes', 'Recién nacido con peso menor a 1500 g o edad gestacional menor de 32 semanas', 'Recién nacido con vacunación completa', 'C', 'La guía enumera entre los criterios de riesgo neurológico el peso al nacer menor de 1500 g o la edad gestacional menor de 32 semanas, junto con otros criterios como ventilación mecánica prolongada, hiperbilirrubinemia >20 mg, convulsiones, sepsis/meningitis/encefalitis, entre otros. Referencia: Atención de seguimiento y reevaluación del neonato y menor de 2 meses, Problemas que causan discapacidad, Riesgo neurológico, p. 65.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('cd31900f-3b34-594a-830e-72747ce7cfd6', 'Caso clínico: Un recién nacido pesa 6 libras y 8 onzas según la báscula utilizada en el hogar. Según la tabla de conversión de la guía, ¿cuál es el peso equivalente en gramos?', '2722 g', '2268 g', '3062 g', '2948 g', 'D', 'Según la tabla de conversión de libras y onzas a gramos de la guía, para 6 libras y 8 onzas (leyendo 6 en la escala de libras y 8 en la escala de onzas) el resultado es 2948 gramos. Referencia: Tabla de conversión, Convertir libras y onzas a gramos, p. 89.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('eb4747eb-fa9a-5a09-9db4-5ef768c4f1c3', 'Según el procedimiento descrito en la guía para colocar una sonda nasogástrica en niñas y niños menores de 5 años, ¿cómo se mide la distancia a la que se debe insertar la sonda?', 'Sosteniendo la punta de la sonda contra la nariz, se mide la distancia desde la nariz hasta el lóbulo del oído, y luego hasta la apófisis xifoides del esternón (epigastrio)', 'Desde la punta de la nariz hasta el ombligo', 'Una distancia fija de 20 cm en todos los casos', 'Desde la comisura labial hasta el pabellón auricular únicamente', 'A', 'El procedimiento descrito en la guía indica que, sosteniendo la punta de la sonda contra la nariz de la niña o niño, se debe medir la distancia desde la nariz hasta el lóbulo del oído, y luego hasta la apófisis xifoides del esternón (epigastrio), marcando la sonda a esa altura antes de insertarla. Referencia: Procedimiento para colocar sonda nasogástrica en niñas y niños menores de 5 años, p. 88.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('e81cd38d-845c-59b4-8cef-fa4655a9760f', 'Según el procedimiento descrito en la guía para administrar diazepam por vía rectal, ¿a qué profundidad se debe insertar la jeringa en el recto?', '1 a 2 cm', '4 a 5 cm', '8 a 10 cm', 'No se especifica profundidad, solo se introduce la aguja', 'B', 'La guía indica que, tras extraer la dosis de diazepam con una jeringa de tuberculina (1 mL) y separar la aguja, se debe insertar la jeringa de 4 a 5 cm en el recto e inyectar la solución, sosteniendo luego las nalgas juntas durante algunos minutos. Referencia: Procedimiento para administrar diazepam intrarrectal, Administrar diazepam por vía rectal, p. 88.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('cc0ad979-8751-5ed2-8687-fe4280c4ba51', 'Según el plan de acción para ayudar a los bebés a respirar, si el líquido amniótico tiene meconio y el recién nacido no llora al nacer, ¿cuál es la primera acción indicada?', 'Cortar el cordón umbilical de inmediato antes de cualquier otra acción', 'Iniciar ventilación a presión positiva de inmediato sin secar', 'Secar completamente al recién nacido', 'Aplicar vacuna BCG de inmediato', 'C', 'Según el flujograma del plan de acción de la guía, si hay meconio, la primera acción es secar completamente al recién nacido, y luego verificar si llora; si no llora, se continúa con despejar las vías respiratorias, estimularlo y evaluar la respiración antes de decidir los siguientes pasos. Referencia: Plan de acción, ayudando a los bebés a respirar, flujograma, p. 46.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('e96d7be6-ffe2-509f-a6e2-ffc950f821dd', 'Según la guía, en el seguimiento de moniliasis oral a los 2 días, si la niña o niño se está alimentando bien y la moniliasis ha mejorado, ¿cuál es la conducta correcta?', 'Referir al hospital de todas formas', 'Suspender la nistatina de inmediato por mejoría', 'Cambiar a un antibiótico oral', 'Continuar con nistatina hasta terminar los 5 días de tratamiento', 'D', 'La guía indica que en el seguimiento de moniliasis oral, si esta ha mejorado y la niña o niño se está alimentando bien, se debe continuar con la nistatina hasta terminar los 5 días de tratamiento, sin suspenderlo antes de completar el esquema. Referencia: Atención de seguimiento y reevaluación del neonato y menor de 2 meses, Moniliasis oral, después de 2 días, p. 64.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('8f52921a-a191-5256-966d-d20f7c2d1932', 'Según la guía, en el seguimiento de ictericia a 1 día, si las plantas y palmas del recién nacido están amarillas, ¿cuál es la conducta correcta?', 'REFERIR al hospital', 'Continuar la observación en casa sin cambios', 'Suspender la lactancia materna temporalmente', 'Esperar hasta que el niño cumpla 2 semanas de edad', 'A', 'La guía indica que, en el seguimiento de ictericia después de 1 día, si las plantas y palmas están amarillas, se debe REFERIR al hospital, dado que la ictericia palmoplantar es un signo de alarma que sugiere hiperbilirrubinemia significativa. Referencia: Atención de seguimiento y reevaluación del neonato y menor de 2 meses, Ictericia, después de 1 día, p. 64.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('b919e78d-50b2-5510-b1fa-49acfa9ee420', 'Según la guía, ¿cuál es la recomendación correcta sobre el momento del primer baño del recién nacido?', 'Bañarlo inmediatamente después de nacer para eliminar el vérnix', 'Esperar de 12 a 24 horas después del nacimiento para dar el primer baño', 'No bañarlo nunca durante el primer mes de vida', 'Bañarlo únicamente si presenta fiebre', 'B', 'La guía indica explícitamente esperar de 12 a 24 horas después del nacimiento para dar a la recién nacida o recién nacido su primer baño, con el fin de prevenir la hipotermia, ya que el baño inmediato puede provocar pérdida de calor corporal. Referencia: Cuidados esenciales de la recién nacida o recién nacido en el establecimiento de salud, Cuidados esenciales y rutinarios, p. 51.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('b4a7b7fe-d43f-5c96-84c2-b79795734808', 'Según la guía, ¿cuáles de los siguientes son signos de alarma por los que se debe recomendar a la madre que regrese de inmediato al establecimiento de salud con su recién nacido?', 'Sueño tranquilo después de cada toma', 'Aumento de peso adecuado y buena succión', 'Se mueve poco o se ve mal (letárgico), no puede lactar o lacta mal, vomita todo lo que come, está muy caliente o se pone frío, o presenta ictericia o cianosis', 'Deposiciones normales de color amarillo', 'C', 'La guía enumera como signos de alarma para regresar de inmediato: que el recién nacido se mueva poco o se vea mal (letárgico), no pueda lactar o lacte mal, vomite todo lo que come, esté muy caliente o se ponga frío, no respire o le cueste respirar, tenga secreción purulenta en ojos u ombligo, sangre en las heces, esté irritable, o presente ictericia (se pone amarillo) o cianosis (se pone morado). Referencia: Orientar a la madre o acompañante sobre cuidados generales de la recién nacida o recién nacido (RN) en el hogar, Recomendar a la madre que vuelva de inmediato, p. 54.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente'),
  ('7cbcece0-8de0-5072-90f4-d720e26f838d', 'Caso clínico: Durante una consulta de seguimiento, el personal de salud identifica que la persona que cuida al lactante es su hermana de 10 años, ya que la madre trabaja todo el día. Según los criterios de evaluación del riesgo social de la guía, ¿cuál es la interpretación correcta de este hallazgo?', 'Este criterio solo aplica a partir de los 2 años de edad del lactante', 'No amerita ninguna acción porque el resto de indicadores puede ser normal', 'Solo se considera riesgo social si además hay pobreza extrema comprobada', 'Este único criterio (persona que cuida es otra niña o niño) ya clasifica al lactante con riesgo social, requiriendo observación, visita domiciliaria o ingreso hospitalario según corresponda', 'D', 'Uno de los criterios explícitos de investigación de riesgo social es si la persona que cuida a la niña o niño es otra niña o niño, madre adolescente o persona con discapacidad. Según la interpretación de la guía, basta con UN SOLO criterio positivo para clasificar al lactante con riesgo social, lo que exige observación en el establecimiento de salud, visita domiciliaria o ingreso hospitalario según corresponda. Referencia: Evaluación del riesgo social, Criterios de evaluación a investigar e Interpretación, p. 90.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'AIEPI Clínico MSP Ecuador 2017 — Banco Docente')
